window.KS4SRC["efficiency"] = {"common_mistake": "Efficiency = useful output \u00f7 TOTAL INPUT \u2014 not useful \u00f7 wasted. Result must be \u2264 1 (\u2264 100%). If your answer exceeds 1, you have divided the wrong way. Wasted energy = total input \u2212 useful output (not the denominator).", "equations": ["efficiency = useful output energy \u00f7 total input energy", "efficiency = useful power output \u00f7 total power input", "efficiency (%) = (useful output \u00f7 total input) \u00d7 100"], "fifas": [{"label": "Efficiency Calculation", "question": "A car engine uses 20,000 J of chemical energy and produces 7,000 J of useful kinetic energy. Calculate its efficiency.", "steps": [["F", "efficiency = useful output energy \u00f7 total input energy"], ["I", "efficiency = 7000 \u00f7 20,000"], ["F", "efficiency = 0.35"], ["A", "efficiency = 0.35 (35%)"]]}], "higher": "Describe and evaluate specific methods to increase the efficiency of a given energy transfer \u2014 e.g. lubrication reduces friction losses, streamlining reduces air resistance, thermal insulation reduces heat loss, LED technology reduces thermal waste in lighting, regenerative braking recovers kinetic energy. Evaluate cost-effectiveness and practicality of each improvement.", "key_note": "Efficiency = useful output \u00f7 total input (decimal, 0\u20131) or \u00d7 100 for %. Wasted = total \u2212 useful. Sankey diagrams: arrow width \u221d energy amount. Improve: reduce friction (lube), reduce air resistance (streamline), reduce heat loss (insulation), use LEDs. Max efficiency = 100% (never exceeded).", "matching": {"instruction": "Match each device to its efficiency.", "pairs": [["0.75 (75%)", "Motor: 300 J input, 225 J useful mechanical output \u2014 225\u00f7300"], ["0.10 (10%)", "Incandescent bulb: 100 J electrical, 10 J light \u2014 10\u00f7100"], ["0.40 (40%)", "Engine: 500 J chemical, 200 J kinetic \u2014 200\u00f7500"], ["0.90 (90%)", "LED lamp: 100 J electrical, 90 J light \u2014 90\u00f7100"]], "title": "Efficiency Values"}, "quiz": {"CF": [{"opts": [["200 J \u2014 useful = 0.6 \u00d7 500 = 300 J; wasted = 500 \u2212 300 = 200 J", true], ["300 J \u2014 this is the useful output, not the wasted amount", false], ["500 J \u2014 all energy is wasted at efficiency 0.6", false], ["833 J \u2014 dividing 500 \u00f7 0.6", false]], "q": "A device has efficiency 0.6 and is supplied with 500 J. How much energy is wasted?", "wrong_explanations": {"1": "300 J is the USEFUL output (60% of 500). WASTED = total \u2212 useful = 500 \u2212 300 = 200 J.", "2": "At efficiency 0.6, only 40% (200 J) is wasted \u2014 not all 500 J.", "3": "500 \u00f7 0.6 = 833 J: this would be the input needed to get 500 J useful output, not the wasted energy."}}, {"opts": [["89 J/s \u2014 LED wastes 1 J/s, bulb wastes 90 J/s; difference = 89 J/s", true], ["0 J/s \u2014 both produce the same useful light so waste must be equal", false], ["10 J/s \u2014 the useful output is 10 J/s so waste is also 10 J/s", false], ["100 J/s \u2014 the bulb uses 100 J/s so wastes all of it", false]], "q": "An LED uses 11 J/s total and produces 10 J/s of light. A filament bulb produces the same 10 J/s of light but uses 100 J/s. How much more energy per second does the bulb waste?", "wrong_explanations": {"1": "Same USEFUL output does NOT mean same waste. LED: wastes 11 \u2212 10 = 1 J/s. Bulb: wastes 100 \u2212 10 = 90 J/s. Difference = 89 J/s.", "2": "Wasted = total \u2212 useful. The TOTAL inputs are very different (11 vs 100 J/s).", "3": "Bulb uses 100 J/s but 10 J/s is useful light \u2014 it wastes 90 J/s, not 100 J/s."}}], "CH": [{"opts": [["200 J \u2014 useful = 0.6 \u00d7 500 = 300 J; wasted = 500 \u2212 300 = 200 J", true], ["300 J \u2014 this is the useful output, not the wasted amount", false], ["500 J \u2014 all energy is wasted at efficiency 0.6", false], ["833 J \u2014 dividing 500 \u00f7 0.6", false]], "q": "A device has efficiency 0.6 and is supplied with 500 J. How much energy is wasted?", "wrong_explanations": {"1": "300 J is the USEFUL output (60% of 500). WASTED = total \u2212 useful = 500 \u2212 300 = 200 J.", "2": "At efficiency 0.6, only 40% (200 J) is wasted \u2014 not all 500 J.", "3": "500 \u00f7 0.6 = 833 J: this would be the input needed to get 500 J useful output, not the wasted energy."}}, {"opts": [["89 J/s \u2014 LED wastes 1 J/s, bulb wastes 90 J/s; difference = 89 J/s", true], ["0 J/s \u2014 both produce the same useful light so waste must be equal", false], ["10 J/s \u2014 the useful output is 10 J/s so waste is also 10 J/s", false], ["100 J/s \u2014 the bulb uses 100 J/s so wastes all of it", false]], "q": "An LED uses 11 J/s total and produces 10 J/s of light. A filament bulb produces the same 10 J/s of light but uses 100 J/s. How much more energy per second does the bulb waste?", "wrong_explanations": {"1": "Same USEFUL output does NOT mean same waste. LED: wastes 11 \u2212 10 = 1 J/s. Bulb: wastes 100 \u2212 10 = 90 J/s. Difference = 89 J/s.", "2": "Wasted = total \u2212 useful. The TOTAL inputs are very different (11 vs 100 J/s).", "3": "Bulb uses 100 J/s but 10 J/s is useful light \u2014 it wastes 90 J/s, not 100 J/s."}}], "TF": [{"opts": [["200 J \u2014 useful = 0.6 \u00d7 500 = 300 J; wasted = 500 \u2212 300 = 200 J", true], ["300 J \u2014 this is the useful output, not the wasted amount", false], ["500 J \u2014 all energy is wasted at efficiency 0.6", false], ["833 J \u2014 dividing 500 \u00f7 0.6", false]], "q": "A device has efficiency 0.6 and is supplied with 500 J. How much energy is wasted?", "wrong_explanations": {"1": "300 J is the USEFUL output (60% of 500). WASTED = total \u2212 useful = 500 \u2212 300 = 200 J.", "2": "At efficiency 0.6, only 40% (200 J) is wasted \u2014 not all 500 J.", "3": "500 \u00f7 0.6 = 833 J: this would be the input needed to get 500 J useful output, not the wasted energy."}}, {"opts": [["89 J/s \u2014 LED wastes 1 J/s, bulb wastes 90 J/s; difference = 89 J/s", true], ["0 J/s \u2014 both produce the same useful light so waste must be equal", false], ["10 J/s \u2014 the useful output is 10 J/s so waste is also 10 J/s", false], ["100 J/s \u2014 the bulb uses 100 J/s so wastes all of it", false]], "q": "An LED uses 11 J/s total and produces 10 J/s of light. A filament bulb produces the same 10 J/s of light but uses 100 J/s. How much more energy per second does the bulb waste?", "wrong_explanations": {"1": "Same USEFUL output does NOT mean same waste. LED: wastes 11 \u2212 10 = 1 J/s. Bulb: wastes 100 \u2212 10 = 90 J/s. Difference = 89 J/s.", "2": "Wasted = total \u2212 useful. The TOTAL inputs are very different (11 vs 100 J/s).", "3": "Bulb uses 100 J/s but 10 J/s is useful light \u2014 it wastes 90 J/s, not 100 J/s."}}], "TH": [{"opts": [["200 J \u2014 useful = 0.6 \u00d7 500 = 300 J; wasted = 500 \u2212 300 = 200 J", true], ["300 J \u2014 this is the useful output, not the wasted amount", false], ["500 J \u2014 all energy is wasted at efficiency 0.6", false], ["833 J \u2014 dividing 500 \u00f7 0.6", false]], "q": "A device has efficiency 0.6 and is supplied with 500 J. How much energy is wasted?", "wrong_explanations": {"1": "300 J is the USEFUL output (60% of 500). WASTED = total \u2212 useful = 500 \u2212 300 = 200 J.", "2": "At efficiency 0.6, only 40% (200 J) is wasted \u2014 not all 500 J.", "3": "500 \u00f7 0.6 = 833 J: this would be the input needed to get 500 J useful output, not the wasted energy."}}, {"opts": [["89 J/s \u2014 LED wastes 1 J/s, bulb wastes 90 J/s; difference = 89 J/s", true], ["0 J/s \u2014 both produce the same useful light so waste must be equal", false], ["10 J/s \u2014 the useful output is 10 J/s so waste is also 10 J/s", false], ["100 J/s \u2014 the bulb uses 100 J/s so wastes all of it", false]], "q": "An LED uses 11 J/s total and produces 10 J/s of light. A filament bulb produces the same 10 J/s of light but uses 100 J/s. How much more energy per second does the bulb waste?", "wrong_explanations": {"1": "Same USEFUL output does NOT mean same waste. LED: wastes 11 \u2212 10 = 1 J/s. Bulb: wastes 100 \u2212 10 = 90 J/s. Difference = 89 J/s.", "2": "Wasted = total \u2212 useful. The TOTAL inputs are very different (11 vs 100 J/s).", "3": "Bulb uses 100 J/s but 10 J/s is useful light \u2014 it wastes 90 J/s, not 100 J/s."}}]}, "summary": "Calculate efficiency as a decimal or percentage and interpret Sankey diagrams.", "theory": [{"content": "EFFICIENCY measures what fraction of total input energy becomes USEFUL output.\n\nNo device is 100% efficient \u2014 some energy is always dissipated as thermal energy or sound.\n\nEQUATIONS:\nefficiency = useful output energy \u00f7 total input energy\nefficiency = useful power output \u00f7 total power input\n\nExpress as:\nDECIMAL: 0 to 1 (e.g. 0.75)\nPERCENTAGE: multiply decimal by 100 (e.g. 75%)\n\nMax efficiency = 1 (100%) \u2014 impossible in practice.\n\nEXAMPLE:\nMotor: 200 J electrical input, 150 J useful mechanical output, 50 J wasted as heat.\nEfficiency = 150 \u00f7 200 = 0.75 = 75%\nWasted = 200 \u2212 150 = 50 J", "heading": "Efficiency \u2014 Definition and Equations"}, {"content": "A SANKEY DIAGRAM shows energy transfers visually:\nArrow WIDTH is proportional to the amount of energy.\nInput arrow on the left. Useful output arrow goes right. Wasted outputs go downward.\n\nReading a Sankey diagram:\nEfficiency = width of useful output \u00f7 width of input arrow.\nThe input arrow = sum of ALL output arrows.\n\nEXAMPLE \u2014 incandescent bulb (very inefficient):\nInput: 100 J electrical\nUseful light output: 10 J (thin right arrow)\nWasted heat: 90 J (wide downward arrow)\nEfficiency = 10 \u00f7 100 = 0.10 = 10%\n\nEXAMPLE \u2014 LED bulb (efficient):\nInput: 100 J\nUseful light: 90 J\nWasted heat: 10 J\nEfficiency = 90 \u00f7 100 = 0.90 = 90%", "heading": "Sankey Diagrams"}, {"content": "REDUCE FRICTION: lubricate moving parts \u2192 less thermal wasted.\nREDUCE AIR RESISTANCE: streamlined shapes \u2192 less energy to air.\nBETTER INSULATION: less thermal energy escapes hot devices.\nBETTER COMPONENTS: LED lights instead of filament bulbs \u2192 more light, less heat.\nREGENERATIVE BRAKING: hybrid/electric cars capture braking KE \u2192 stored in battery rather than wasted as thermal.\n\nWHY EFFICIENCY MATTERS:\nHigher efficiency \u2192 less fuel for same useful output \u2192 lower costs.\nLess fuel \u2192 less CO\u2082 \u2192 lower environmental impact.\nBut: no device can exceed 100% efficiency.", "heading": "Improving Efficiency"}]};
window.KS4SRC["heart-blood-vessels"] = {"common_mistake": "Arteries do NOT always carry oxygenated blood. The PULMONARY ARTERY carries DEOXYGENATED blood from the heart to the lungs. Veins do NOT always carry deoxygenated blood \u2014 the PULMONARY VEIN carries OXYGENATED blood from the lungs to the heart. The rule is: Arteries = Away from heart. Veins = to heart. Not about oxygen content.", "higher": "Artificial pacemakers correct irregular heart rhythms. Faulty heart valves can be replaced with biological valves (from pigs or cows) or mechanical valves. Artificial hearts maintain circulation while waiting for a transplant or during recovery. Students should be able to evaluate the advantages and disadvantages of drug treatment vs mechanical devices vs transplant for cardiovascular disease.", "key_note": "Left ventricle = thickest wall (pumps to whole body). Right ventricle = pumps to lungs only. Arteries: away, thick walls, high pressure. Veins: to heart, valves, low pressure. Capillaries: one cell thick, exchange site.", "matching": {"instruction": "Match each structure to what it does.", "pairs": [["Left ventricle", "Pumps oxygenated blood to the whole body via the aorta \u2014 thickest walls"], ["Right ventricle", "Pumps deoxygenated blood to the lungs via the pulmonary artery"], ["Valves", "Prevent backflow of blood \u2014 open and close with pressure changes"], ["Coronary arteries", "Supply the heart muscle itself with oxygenated blood"], ["Pulmonary vein", "Carries oxygenated blood FROM the lungs TO the left atrium"], ["Vena cava", "Carries deoxygenated blood FROM the body TO the right atrium"]], "title": "Match the Heart Structure to its Function"}, "quiz": {"CF": [{"opts": [["It pumps blood to the whole body \u2014 needs much higher pressure than the right ventricle which only pumps to the nearby lungs", true], ["It receives more blood than the right ventricle so needs to be stronger", false], ["The left side of the body is larger so the heart must compensate", false], ["The left ventricle contains oxygenated blood which is heavier", false]], "q": "Why does the left ventricle have thicker walls than the right ventricle?", "wrong_explanations": {"1": "Both ventricles receive the same volume of blood per beat \u2014 the difference is in the distance the blood must be pumped, not the volume.", "2": "Body size has no relationship to heart wall thickness \u2014 it's purely about pumping distance and pressure.", "3": "Oxygenated and deoxygenated blood have essentially the same density \u2014 the thickness difference is purely about pressure requirements."}}, {"opts": [["Deoxygenated blood \u2014 it has just returned from the body and needs to be reoxygenated", true], ["Oxygenated blood \u2014 all arteries carry oxygenated blood", false], ["A mixture of oxygenated and deoxygenated blood", false], ["Blood with no red blood cells \u2014 only plasma", false]], "q": "The pulmonary artery carries blood from the heart to the lungs. What type of blood does it carry?", "wrong_explanations": {"1": "This is the most common mistake in this topic! Arteries carry blood AWAY from the heart \u2014 but the pulmonary artery specifically carries deoxygenated blood to be oxygenated in the lungs.", "2": "Blood in the heart is kept completely separate \u2014 left side carries oxygenated, right side carries deoxygenated. There is no mixing.", "3": "All blood contains red blood cells \u2014 plasma alone would have no oxygen-carrying capacity."}}, {"opts": [["Blood pressure in veins is low \u2014 valves prevent backflow. Arterial pressure is high enough to keep blood flowing in the right direction", true], ["Arteries have thicker walls so they don't need valves", false], ["Veins carry deoxygenated blood which needs extra support to flow", false], ["Valves in arteries would slow down the high-pressure blood flow too much", false]], "q": "Why do veins have valves but arteries do not?", "wrong_explanations": {"1": "Wall thickness helps arteries withstand pressure \u2014 but valves are specifically about preventing BACKFLOW, which is a problem in low-pressure veins, not high-pressure arteries.", "2": "The oxygen content of blood has nothing to do with the need for valves \u2014 the PRESSURE is what matters.", "3": "Valves in veins do slightly slow flow, but that's acceptable \u2014 their role is to prevent dangerous backflow in low-pressure vessels."}}, {"opts": [["Walls are only one cell thick \u2014 very short diffusion distance. Dense network = large surface area", true], ["They have the highest blood pressure of all blood vessels", false], ["They carry both oxygenated and deoxygenated blood simultaneously", false], ["They have valves to keep substances moving in one direction", false]], "q": "What makes capillaries efficient at exchanging substances?", "wrong_explanations": {"1": "Capillaries have the LOWEST blood pressure \u2014 that is why they can be one cell thick without bursting.", "2": "Capillaries carry either oxygenated or deoxygenated blood depending on location \u2014 not both at once.", "3": "Capillaries have no valves \u2014 substances move by DIFFUSION driven by concentration gradients."}}], "CH": [{"opts": [["It pumps blood to the whole body \u2014 needs much higher pressure than the right ventricle which only pumps to the nearby lungs", true], ["It receives more blood than the right ventricle so needs to be stronger", false], ["The left side of the body is larger so the heart must compensate", false], ["The left ventricle contains oxygenated blood which is heavier", false]], "q": "Why does the left ventricle have thicker walls than the right ventricle?", "wrong_explanations": {"1": "Both ventricles receive the same volume of blood per beat \u2014 the difference is in the distance the blood must be pumped, not the volume.", "2": "Body size has no relationship to heart wall thickness \u2014 it's purely about pumping distance and pressure.", "3": "Oxygenated and deoxygenated blood have essentially the same density \u2014 the thickness difference is purely about pressure requirements."}}, {"opts": [["Deoxygenated blood \u2014 it has just returned from the body and needs to be reoxygenated", true], ["Oxygenated blood \u2014 all arteries carry oxygenated blood", false], ["A mixture of oxygenated and deoxygenated blood", false], ["Blood with no red blood cells \u2014 only plasma", false]], "q": "The pulmonary artery carries blood from the heart to the lungs. What type of blood does it carry?", "wrong_explanations": {"1": "This is the most common mistake in this topic! Arteries carry blood AWAY from the heart \u2014 but the pulmonary artery specifically carries deoxygenated blood to be oxygenated in the lungs.", "2": "Blood in the heart is kept completely separate \u2014 left side carries oxygenated, right side carries deoxygenated. There is no mixing.", "3": "All blood contains red blood cells \u2014 plasma alone would have no oxygen-carrying capacity."}}, {"opts": [["Blood pressure in veins is low \u2014 valves prevent backflow. Arterial pressure is high enough to keep blood flowing in the right direction", true], ["Arteries have thicker walls so they don't need valves", false], ["Veins carry deoxygenated blood which needs extra support to flow", false], ["Valves in arteries would slow down the high-pressure blood flow too much", false]], "q": "Why do veins have valves but arteries do not?", "wrong_explanations": {"1": "Wall thickness helps arteries withstand pressure \u2014 but valves are specifically about preventing BACKFLOW, which is a problem in low-pressure veins, not high-pressure arteries.", "2": "The oxygen content of blood has nothing to do with the need for valves \u2014 the PRESSURE is what matters.", "3": "Valves in veins do slightly slow flow, but that's acceptable \u2014 their role is to prevent dangerous backflow in low-pressure vessels."}}, {"opts": [["Walls are only one cell thick \u2014 very short diffusion distance. Dense network = large surface area", true], ["They have the highest blood pressure of all blood vessels", false], ["They carry both oxygenated and deoxygenated blood simultaneously", false], ["They have valves to keep substances moving in one direction", false]], "q": "What makes capillaries efficient at exchanging substances?", "wrong_explanations": {"1": "Capillaries have the LOWEST blood pressure \u2014 that is why they can be one cell thick without bursting.", "2": "Capillaries carry either oxygenated or deoxygenated blood depending on location \u2014 not both at once.", "3": "Capillaries have no valves \u2014 substances move by DIFFUSION driven by concentration gradients."}}], "TF": [{"opts": [["It pumps blood to the whole body \u2014 needs much higher pressure than the right ventricle which only pumps to the nearby lungs", true], ["It receives more blood than the right ventricle so needs to be stronger", false], ["The left side of the body is larger so the heart must compensate", false], ["The left ventricle contains oxygenated blood which is heavier", false]], "q": "Why does the left ventricle have thicker walls than the right ventricle?", "wrong_explanations": {"1": "Both ventricles receive the same volume of blood per beat \u2014 the difference is in the distance the blood must be pumped, not the volume.", "2": "Body size has no relationship to heart wall thickness \u2014 it's purely about pumping distance and pressure.", "3": "Oxygenated and deoxygenated blood have essentially the same density \u2014 the thickness difference is purely about pressure requirements."}}, {"opts": [["Deoxygenated blood \u2014 it has just returned from the body and needs to be reoxygenated", true], ["Oxygenated blood \u2014 all arteries carry oxygenated blood", false], ["A mixture of oxygenated and deoxygenated blood", false], ["Blood with no red blood cells \u2014 only plasma", false]], "q": "The pulmonary artery carries blood from the heart to the lungs. What type of blood does it carry?", "wrong_explanations": {"1": "This is the most common mistake in this topic! Arteries carry blood AWAY from the heart \u2014 but the pulmonary artery specifically carries deoxygenated blood to be oxygenated in the lungs.", "2": "Blood in the heart is kept completely separate \u2014 left side carries oxygenated, right side carries deoxygenated. There is no mixing.", "3": "All blood contains red blood cells \u2014 plasma alone would have no oxygen-carrying capacity."}}, {"opts": [["Blood pressure in veins is low \u2014 valves prevent backflow. Arterial pressure is high enough to keep blood flowing in the right direction", true], ["Arteries have thicker walls so they don't need valves", false], ["Veins carry deoxygenated blood which needs extra support to flow", false], ["Valves in arteries would slow down the high-pressure blood flow too much", false]], "q": "Why do veins have valves but arteries do not?", "wrong_explanations": {"1": "Wall thickness helps arteries withstand pressure \u2014 but valves are specifically about preventing BACKFLOW, which is a problem in low-pressure veins, not high-pressure arteries.", "2": "The oxygen content of blood has nothing to do with the need for valves \u2014 the PRESSURE is what matters.", "3": "Valves in veins do slightly slow flow, but that's acceptable \u2014 their role is to prevent dangerous backflow in low-pressure vessels."}}, {"opts": [["Walls are only one cell thick \u2014 very short diffusion distance. Dense network = large surface area", true], ["They have the highest blood pressure of all blood vessels", false], ["They carry both oxygenated and deoxygenated blood simultaneously", false], ["They have valves to keep substances moving in one direction", false]], "q": "What makes capillaries efficient at exchanging substances?", "wrong_explanations": {"1": "Capillaries have the LOWEST blood pressure \u2014 that is why they can be one cell thick without bursting.", "2": "Capillaries carry either oxygenated or deoxygenated blood depending on location \u2014 not both at once.", "3": "Capillaries have no valves \u2014 substances move by DIFFUSION driven by concentration gradients."}}], "TH": [{"opts": [["It pumps blood to the whole body \u2014 needs much higher pressure than the right ventricle which only pumps to the nearby lungs", true], ["It receives more blood than the right ventricle so needs to be stronger", false], ["The left side of the body is larger so the heart must compensate", false], ["The left ventricle contains oxygenated blood which is heavier", false]], "q": "Why does the left ventricle have thicker walls than the right ventricle?", "wrong_explanations": {"1": "Both ventricles receive the same volume of blood per beat \u2014 the difference is in the distance the blood must be pumped, not the volume.", "2": "Body size has no relationship to heart wall thickness \u2014 it's purely about pumping distance and pressure.", "3": "Oxygenated and deoxygenated blood have essentially the same density \u2014 the thickness difference is purely about pressure requirements."}}, {"opts": [["Deoxygenated blood \u2014 it has just returned from the body and needs to be reoxygenated", true], ["Oxygenated blood \u2014 all arteries carry oxygenated blood", false], ["A mixture of oxygenated and deoxygenated blood", false], ["Blood with no red blood cells \u2014 only plasma", false]], "q": "The pulmonary artery carries blood from the heart to the lungs. What type of blood does it carry?", "wrong_explanations": {"1": "This is the most common mistake in this topic! Arteries carry blood AWAY from the heart \u2014 but the pulmonary artery specifically carries deoxygenated blood to be oxygenated in the lungs.", "2": "Blood in the heart is kept completely separate \u2014 left side carries oxygenated, right side carries deoxygenated. There is no mixing.", "3": "All blood contains red blood cells \u2014 plasma alone would have no oxygen-carrying capacity."}}, {"opts": [["Blood pressure in veins is low \u2014 valves prevent backflow. Arterial pressure is high enough to keep blood flowing in the right direction", true], ["Arteries have thicker walls so they don't need valves", false], ["Veins carry deoxygenated blood which needs extra support to flow", false], ["Valves in arteries would slow down the high-pressure blood flow too much", false]], "q": "Why do veins have valves but arteries do not?", "wrong_explanations": {"1": "Wall thickness helps arteries withstand pressure \u2014 but valves are specifically about preventing BACKFLOW, which is a problem in low-pressure veins, not high-pressure arteries.", "2": "The oxygen content of blood has nothing to do with the need for valves \u2014 the PRESSURE is what matters.", "3": "Valves in veins do slightly slow flow, but that's acceptable \u2014 their role is to prevent dangerous backflow in low-pressure vessels."}}, {"opts": [["Walls are only one cell thick \u2014 very short diffusion distance. Dense network = large surface area", true], ["They have the highest blood pressure of all blood vessels", false], ["They carry both oxygenated and deoxygenated blood simultaneously", false], ["They have valves to keep substances moving in one direction", false]], "q": "What makes capillaries efficient at exchanging substances?", "wrong_explanations": {"1": "Capillaries have the LOWEST blood pressure \u2014 that is why they can be one cell thick without bursting.", "2": "Capillaries carry either oxygenated or deoxygenated blood depending on location \u2014 not both at once.", "3": "Capillaries have no valves \u2014 substances move by DIFFUSION driven by concentration gradients."}}]}, "summary": "Describe the structure and function of the heart, the double circulatory system and the three types of blood vessel.", "theory": [{"content": "Humans have a DOUBLE circulatory system \u2014 the blood passes through the heart twice for every complete circuit of the body.\n\nCircuit 1 \u2014 PULMONARY CIRCULATION:\nRight side of heart \u2192 lungs \u2192 left side of heart.\nDeoxygenated blood is pumped to the lungs to pick up oxygen and lose carbon dioxide.\n\nCircuit 2 \u2014 SYSTEMIC CIRCULATION:\nLeft side of heart \u2192 body organs and tissues \u2192 right side of heart.\nOxygenated blood is delivered to all body tissues at high pressure.\n\nWHY DOUBLE? Having two separate circuits means oxygenated blood is always kept separate from deoxygenated blood, and the left side can pump oxygenated blood to the body at high pressure \u2014 ensuring efficient oxygen delivery to even distant organs.", "heading": "The Double Circulatory System"}, {"content": "The heart has FOUR chambers:\nRight atrium \u2014 receives deoxygenated blood from the body via the VENA CAVA.\nRight ventricle \u2014 pumps deoxygenated blood to the lungs via the PULMONARY ARTERY.\nLeft atrium \u2014 receives oxygenated blood from the lungs via the PULMONARY VEIN.\nLeft ventricle \u2014 pumps oxygenated blood to the whole body via the AORTA.\n\nThe LEFT VENTRICLE has much thicker, more muscular walls than the right ventricle because it must pump blood to the entire body \u2014 a much greater distance and requiring much higher pressure than the right ventricle (which only pumps to the nearby lungs).\n\nVALVES prevent blood flowing backwards:\nAtrioventricular (AV) valves \u2014 between atria and ventricles.\nSemilunar valves \u2014 in the pulmonary artery and aorta.\nValves open when pressure is higher on one side and snap shut to prevent backflow \u2014 this creates the 'lub-dub' heart sound.\n\nThe heart is made of CARDIAC MUSCLE \u2014 a special type of muscle that contracts and relaxes rhythmically, never getting tired.\n\nThe CORONARY ARTERIES supply the heart muscle itself with oxygenated blood. If these are blocked, the heart muscle is deprived of oxygen \u2014 causing a heart attack.", "heading": "Structure of the Heart"}, {"content": "Arteries carry blood AWAY from the heart.\n\nKey features:\nThick, muscular walls \u2014 to withstand the high pressure of blood pumped directly from the heart.\nElastic fibres in the walls \u2014 stretch as blood surges through with each heartbeat, then recoil to maintain smooth blood flow.\nNarrow lumen (central channel) \u2014 helps maintain high pressure.\nNO valves \u2014 pressure is high enough to keep blood flowing in the correct direction.\n\nMost arteries carry oxygenated blood \u2014 EXCEPT the PULMONARY ARTERY, which carries deoxygenated blood from the right ventricle to the lungs.\n\nMemory tip: Arteries = Away from heart.", "heading": "Arteries"}, {"content": "Veins carry blood TOWARDS the heart.\n\nKey features:\nThinner walls \u2014 blood pressure is much lower in veins (far from the heart).\nWider lumen \u2014 accommodates the slower, lower-pressure flow.\nVALVES \u2014 essential to prevent backflow of blood. Without valves, gravity and low pressure would allow blood to pool in the legs and flow backwards.\n\nMost veins carry deoxygenated blood \u2014 EXCEPT the PULMONARY VEIN, which carries oxygenated blood from the lungs to the left atrium.\n\nMemory tip: Veins \u2192 towards the heart. Valves in Veins.", "heading": "Veins"}, {"content": "Capillaries are the smallest blood vessels \u2014 connecting arteries to veins.\n\nKey features:\nWalls are only ONE CELL THICK \u2014 the shortest possible diffusion distance.\nVery narrow \u2014 red blood cells must squeeze through in single file.\nForm a dense network throughout all body tissues.\nVery large total surface area \u2014 maximises exchange.\n\nAt the capillaries, EXCHANGE of substances takes place:\nOxygen and glucose diffuse OUT of the blood into body cells.\nCarbon dioxide and waste products diffuse INTO the blood from cells.\n\nThis exchange happens by DIFFUSION down concentration gradients \u2014 no energy required.", "heading": "Capillaries"}]};
window.KS4SRC["water-cycle"] = {"common_mistake": "TRANSPIRATION is the loss of water vapour from PLANT LEAVES through stomata \u2014 it is NOT the same as evaporation from the soil or water surface. Both contribute to atmospheric water, but transpiration is specifically the biological process in plants. Also: precipitation is NOT just rain \u2014 it includes snow, sleet and hail.", "key_note": "Water cycle: evaporation + transpiration \u2192 condensation (clouds) \u2192 precipitation (rain/snow) \u2192 runoff/groundwater \u2192 back to sea. Plants contribute via transpiration. Deforestation reduces transpiration \u2192 less rainfall. Key: water is continuously recycled.", "matching": {"instruction": "Match each stage to its correct description.", "pairs": [["Evaporation", "Heat energy causes water to change from liquid to vapour from oceans, lakes and soil"], ["Transpiration", "Water vapour released by plants through stomata into the atmosphere"], ["Condensation", "Rising water vapour cools and forms tiny liquid droplets \u2014 creating clouds"], ["Precipitation", "Water droplets in clouds fall as rain, snow, sleet or hail"], ["Runoff", "Water flows across the land surface into streams, rivers and eventually back to the sea"]], "title": "Match the Stage of the Water Cycle"}, "quiz": {"CF": [{"opts": [["Through transpiration \u2014 water absorbed from soil is released as water vapour through leaf stomata, returning water to the atmosphere", true], ["By storing water permanently in their cells \u2014 removing it from the cycle", false], ["By producing water as a by-product of photosynthesis", false], ["By preventing precipitation by blocking clouds with their canopy", false]], "q": "How do plants contribute to the water cycle?", "wrong_explanations": {"1": "Plants don't store water permanently \u2014 they continuously take it in and release it. Transpiration is the return pathway to the atmosphere.", "2": "Photosynthesis USES water as a reactant \u2014 it does not produce water as a by-product. Oxygen is the gas product of photosynthesis.", "3": "Forests influence local weather patterns but do not prevent precipitation \u2014 they actually INCREASE local rainfall by contributing to atmospheric water vapour."}}, {"opts": [["Trees release large amounts of water vapour through transpiration \u2014 removing them reduces the water returning to the atmosphere, lowering precipitation", true], ["Trees attract rain clouds \u2014 without trees, clouds move away from the area", false], ["Tree roots release chemicals that trigger condensation in the atmosphere above", false], ["Deforestation increases runoff \u2014 water leaves the area before it can evaporate", false]], "q": "Why does deforestation in tropical areas often lead to reduced local rainfall?", "wrong_explanations": {"1": "Clouds are not 'attracted' to trees \u2014 the mechanism is through transpiration contributing to atmospheric moisture content.", "2": "Roots do not release chemicals that trigger condensation \u2014 their role in the water cycle is absorbing water from soil, which then passes up to leaves and out through transpiration.", "3": "Increased runoff does remove water quickly \u2014 but the PRIMARY reason for reduced local rainfall after deforestation is the loss of transpiration returning water to the atmosphere."}}], "CH": [{"opts": [["Through transpiration \u2014 water absorbed from soil is released as water vapour through leaf stomata, returning water to the atmosphere", true], ["By storing water permanently in their cells \u2014 removing it from the cycle", false], ["By producing water as a by-product of photosynthesis", false], ["By preventing precipitation by blocking clouds with their canopy", false]], "q": "How do plants contribute to the water cycle?", "wrong_explanations": {"1": "Plants don't store water permanently \u2014 they continuously take it in and release it. Transpiration is the return pathway to the atmosphere.", "2": "Photosynthesis USES water as a reactant \u2014 it does not produce water as a by-product. Oxygen is the gas product of photosynthesis.", "3": "Forests influence local weather patterns but do not prevent precipitation \u2014 they actually INCREASE local rainfall by contributing to atmospheric water vapour."}}, {"opts": [["Trees release large amounts of water vapour through transpiration \u2014 removing them reduces the water returning to the atmosphere, lowering precipitation", true], ["Trees attract rain clouds \u2014 without trees, clouds move away from the area", false], ["Tree roots release chemicals that trigger condensation in the atmosphere above", false], ["Deforestation increases runoff \u2014 water leaves the area before it can evaporate", false]], "q": "Why does deforestation in tropical areas often lead to reduced local rainfall?", "wrong_explanations": {"1": "Clouds are not 'attracted' to trees \u2014 the mechanism is through transpiration contributing to atmospheric moisture content.", "2": "Roots do not release chemicals that trigger condensation \u2014 their role in the water cycle is absorbing water from soil, which then passes up to leaves and out through transpiration.", "3": "Increased runoff does remove water quickly \u2014 but the PRIMARY reason for reduced local rainfall after deforestation is the loss of transpiration returning water to the atmosphere."}}], "TF": [{"opts": [["Through transpiration \u2014 water absorbed from soil is released as water vapour through leaf stomata, returning water to the atmosphere", true], ["By storing water permanently in their cells \u2014 removing it from the cycle", false], ["By producing water as a by-product of photosynthesis", false], ["By preventing precipitation by blocking clouds with their canopy", false]], "q": "How do plants contribute to the water cycle?", "wrong_explanations": {"1": "Plants don't store water permanently \u2014 they continuously take it in and release it. Transpiration is the return pathway to the atmosphere.", "2": "Photosynthesis USES water as a reactant \u2014 it does not produce water as a by-product. Oxygen is the gas product of photosynthesis.", "3": "Forests influence local weather patterns but do not prevent precipitation \u2014 they actually INCREASE local rainfall by contributing to atmospheric water vapour."}}, {"opts": [["Trees release large amounts of water vapour through transpiration \u2014 removing them reduces the water returning to the atmosphere, lowering precipitation", true], ["Trees attract rain clouds \u2014 without trees, clouds move away from the area", false], ["Tree roots release chemicals that trigger condensation in the atmosphere above", false], ["Deforestation increases runoff \u2014 water leaves the area before it can evaporate", false]], "q": "Why does deforestation in tropical areas often lead to reduced local rainfall?", "wrong_explanations": {"1": "Clouds are not 'attracted' to trees \u2014 the mechanism is through transpiration contributing to atmospheric moisture content.", "2": "Roots do not release chemicals that trigger condensation \u2014 their role in the water cycle is absorbing water from soil, which then passes up to leaves and out through transpiration.", "3": "Increased runoff does remove water quickly \u2014 but the PRIMARY reason for reduced local rainfall after deforestation is the loss of transpiration returning water to the atmosphere."}}], "TH": [{"opts": [["Through transpiration \u2014 water absorbed from soil is released as water vapour through leaf stomata, returning water to the atmosphere", true], ["By storing water permanently in their cells \u2014 removing it from the cycle", false], ["By producing water as a by-product of photosynthesis", false], ["By preventing precipitation by blocking clouds with their canopy", false]], "q": "How do plants contribute to the water cycle?", "wrong_explanations": {"1": "Plants don't store water permanently \u2014 they continuously take it in and release it. Transpiration is the return pathway to the atmosphere.", "2": "Photosynthesis USES water as a reactant \u2014 it does not produce water as a by-product. Oxygen is the gas product of photosynthesis.", "3": "Forests influence local weather patterns but do not prevent precipitation \u2014 they actually INCREASE local rainfall by contributing to atmospheric water vapour."}}, {"opts": [["Trees release large amounts of water vapour through transpiration \u2014 removing them reduces the water returning to the atmosphere, lowering precipitation", true], ["Trees attract rain clouds \u2014 without trees, clouds move away from the area", false], ["Tree roots release chemicals that trigger condensation in the atmosphere above", false], ["Deforestation increases runoff \u2014 water leaves the area before it can evaporate", false]], "q": "Why does deforestation in tropical areas often lead to reduced local rainfall?", "wrong_explanations": {"1": "Clouds are not 'attracted' to trees \u2014 the mechanism is through transpiration contributing to atmospheric moisture content.", "2": "Roots do not release chemicals that trigger condensation \u2014 their role in the water cycle is absorbing water from soil, which then passes up to leaves and out through transpiration.", "3": "Increased runoff does remove water quickly \u2014 but the PRIMARY reason for reduced local rainfall after deforestation is the loss of transpiration returning water to the atmosphere."}}]}, "summary": "Describe how water is cycled through the environment.", "theory": [{"content": "Water is essential to all life:\nIt is the SOLVENT for all biochemical reactions.\nIt is a REACTANT in photosynthesis and many other reactions.\nIt transports dissolved substances around organisms.\nIt provides structure to plant cells (turgor pressure).\nIt regulates body temperature (through sweating and evaporation).\n\nLike carbon, water is continuously RECYCLED through the environment in the WATER CYCLE (also called the HYDROLOGICAL CYCLE).\n\nThe total amount of water on Earth is effectively fixed \u2014 it moves between stores: oceans, atmosphere, freshwater lakes and rivers, ice caps, groundwater, and living organisms.", "heading": "Why Water Must Be Recycled"}, {"content": "EVAPORATION:\nThe sun's heat energy causes water to evaporate from the surfaces of oceans, lakes, rivers and soil.\nWater changes from liquid to water vapour \u2014 rising into the atmosphere.\n\nTRANSPIRATION:\nPlants release water vapour through their stomata \u2014 a process called TRANSPIRATION.\nIn tropical rainforests, transpiration adds enormous quantities of water to the atmosphere \u2014 maintaining local rainfall patterns.\n\nCONDENSATION:\nAs water vapour rises, it cools.\nCooling causes it to CONDENSE \u2014 changing from vapour back to tiny liquid water droplets.\nThese droplets form CLOUDS and mist.\n\nPRECIPITATION:\nWhen water droplets in clouds collide and join to form larger drops, they fall as PRECIPITATION \u2014 rain, snow, sleet or hail.\n\nRUNOFF AND GROUNDWATER:\nPrecipitation that falls on land either:\nFlows across the surface as RUNOFF \u2014 into streams and rivers \u2192 back to the sea.\nSOAKS INTO the ground to form GROUNDWATER \u2014 extracted by plant roots or flowing slowly to rivers and sea.", "heading": "Stages of the Water Cycle"}, {"content": "Living organisms play an important role in the water cycle:\n\nPLANTS:\nAbsorb water from the soil through root hair cells.\nTransport water up through xylem to leaves.\nRelease water vapour through stomata (transpiration) \u2014 returns water to the atmosphere.\nSoil absorption is helped by the structural effects of plant roots.\n\nANIMALS:\nObtain water by drinking, and from food.\nReturn water to the environment through:\nUrination and defaecation.\nExhaling water vapour.\nSweating.\n\nHUMAN IMPACTS on the water cycle:\nDEFORESTATION \u2014 removing trees reduces transpiration \u2192 less water returned to atmosphere \u2192 reduced local rainfall \u2192 increased risk of drought.\nURBANISATION \u2014 impermeable surfaces (roads, buildings) prevent water soaking into soil \u2192 increased runoff \u2192 flooding.\nIRRIGATION \u2014 withdrawing groundwater for farming can deplete underground reserves.\nCLIMATE CHANGE \u2014 warming increases evaporation \u2192 more intense rainfall events and more severe droughts.", "heading": "Living Organisms and the Water Cycle"}]};
window.KS4SRC["atmospheric-pollutants"] = {"common_mistake": "CO (carbon monoxide) is produced by INCOMPLETE combustion. CO\u2082 is produced by COMPLETE combustion. Both are colourless gases \u2014 but CO is toxic (binds to haemoglobin) while CO\u2082 is not directly toxic at normal concentrations. Catalytic converters reduce CO and NO\u2093 but actually INCREASE CO\u2082 (by converting CO to CO\u2082).", "equations": ["S + O\u2082 \u2192 SO\u2082  (sulfur impurity burning)", "N\u2082 + O\u2082 \u2192 2NO  (in engines at high temperature)", "2CO + 2NO \u2192 2CO\u2082 + N\u2082  (catalytic converter reaction)", "CaCO\u2083 + H\u2082SO\u2084 \u2192 CaSO\u2084 + H\u2082O + CO\u2082  (acid rain dissolving limestone)"], "higher": "Evaluate effectiveness and limitations of pollution control: catalytic converters (reduce CO, NO\u2093 but increase CO\u2082), particulate filters, low-sulfur fuels, electric vehicles (shift emissions to power stations). Evaluate life cycle perspective on different solutions.", "key_note": "Pollutants from fuel combustion: CO (toxic, incomplete combustion), SO\u2082 (acid rain, from sulfur in fuel), NO\u2093 (acid rain, smog, from N\u2082 + O\u2082 at high temperature), particulates (respiratory harm). Acid rain: damages limestone, kills aquatic life. Catalytic converters: convert CO + NO\u2093 \u2192 CO\u2082 + N\u2082.", "matching": {"instruction": "Match each pollutant to its source and main effect.", "pairs": [["Carbon monoxide (CO)", "Incomplete combustion \u2014 toxic gas that prevents oxygen transport in blood"], ["Sulfur dioxide (SO\u2082)", "Sulfur impurities in fuel burned \u2014 causes acid rain damaging buildings and ecosystems"], ["Nitrogen oxides (NO\u2093)", "N\u2082 + O\u2082 at high engine temperatures \u2014 causes acid rain and smog"], ["Particulates (soot)", "Incomplete combustion \u2014 fine particles damage lungs and cause respiratory disease"]], "title": "Pollutant \u2014 Source and Effect"}, "quiz": {"CF": [{"opts": [["CO binds irreversibly to haemoglobin \u2014 preventing red blood cells from carrying oxygen, causing suffocation even in small concentrations", true], ["CO is a coloured gas \u2014 it can be detected visually, making it more alarming", false], ["CO is heavier than air \u2014 it sinks and accumulates at floor level where people breathe", false], ["CO reacts with water in the lungs to form carbonic acid", false]], "q": "Why is carbon monoxide (CO) particularly dangerous compared to carbon dioxide (CO\u2082)?", "wrong_explanations": {"1": "CO is COLOURLESS and ODOURLESS \u2014 this makes it MORE dangerous as it cannot be detected by sight or smell without a detector.", "2": "CO has a density very similar to air \u2014 it doesn't strongly stratify, unlike some heavier gases.", "3": "CO does not react with water to form carbonic acid \u2014 that reaction is for CO\u2082. CO reacts with haemoglobin."}}, {"opts": [["They convert toxic CO and NO\u2093 to CO\u2082 and N\u2082 using platinum and rhodium catalysts", true], ["They filter out solid particulates using a fine mesh \u2014 trapping soot before it leaves the exhaust", false], ["They reduce all emissions including CO\u2082 \u2014 making cars more environmentally friendly overall", false], ["They add oxygen to the exhaust to ensure complete combustion of any remaining fuel", false]], "q": "How do catalytic converters reduce air pollution from cars?", "wrong_explanations": {"1": "Particulate filters are separate devices \u2014 catalytic converters work by CHEMICAL REACTIONS, not filtration.", "2": "Catalytic converters actually INCREASE CO\u2082 (by converting CO to CO\u2082). They do NOT reduce CO\u2082 emissions.", "3": "Catalysts work by providing alternative reaction pathways \u2014 they don't inject additional oxygen into the exhaust."}}], "CH": [{"opts": [["CO binds irreversibly to haemoglobin \u2014 preventing red blood cells from carrying oxygen, causing suffocation even in small concentrations", true], ["CO is a coloured gas \u2014 it can be detected visually, making it more alarming", false], ["CO is heavier than air \u2014 it sinks and accumulates at floor level where people breathe", false], ["CO reacts with water in the lungs to form carbonic acid", false]], "q": "Why is carbon monoxide (CO) particularly dangerous compared to carbon dioxide (CO\u2082)?", "wrong_explanations": {"1": "CO is COLOURLESS and ODOURLESS \u2014 this makes it MORE dangerous as it cannot be detected by sight or smell without a detector.", "2": "CO has a density very similar to air \u2014 it doesn't strongly stratify, unlike some heavier gases.", "3": "CO does not react with water to form carbonic acid \u2014 that reaction is for CO\u2082. CO reacts with haemoglobin."}}, {"opts": [["They convert toxic CO and NO\u2093 to CO\u2082 and N\u2082 using platinum and rhodium catalysts", true], ["They filter out solid particulates using a fine mesh \u2014 trapping soot before it leaves the exhaust", false], ["They reduce all emissions including CO\u2082 \u2014 making cars more environmentally friendly overall", false], ["They add oxygen to the exhaust to ensure complete combustion of any remaining fuel", false]], "q": "How do catalytic converters reduce air pollution from cars?", "wrong_explanations": {"1": "Particulate filters are separate devices \u2014 catalytic converters work by CHEMICAL REACTIONS, not filtration.", "2": "Catalytic converters actually INCREASE CO\u2082 (by converting CO to CO\u2082). They do NOT reduce CO\u2082 emissions.", "3": "Catalysts work by providing alternative reaction pathways \u2014 they don't inject additional oxygen into the exhaust."}}], "TF": [{"opts": [["CO binds irreversibly to haemoglobin \u2014 preventing red blood cells from carrying oxygen, causing suffocation even in small concentrations", true], ["CO is a coloured gas \u2014 it can be detected visually, making it more alarming", false], ["CO is heavier than air \u2014 it sinks and accumulates at floor level where people breathe", false], ["CO reacts with water in the lungs to form carbonic acid", false]], "q": "Why is carbon monoxide (CO) particularly dangerous compared to carbon dioxide (CO\u2082)?", "wrong_explanations": {"1": "CO is COLOURLESS and ODOURLESS \u2014 this makes it MORE dangerous as it cannot be detected by sight or smell without a detector.", "2": "CO has a density very similar to air \u2014 it doesn't strongly stratify, unlike some heavier gases.", "3": "CO does not react with water to form carbonic acid \u2014 that reaction is for CO\u2082. CO reacts with haemoglobin."}}, {"opts": [["They convert toxic CO and NO\u2093 to CO\u2082 and N\u2082 using platinum and rhodium catalysts", true], ["They filter out solid particulates using a fine mesh \u2014 trapping soot before it leaves the exhaust", false], ["They reduce all emissions including CO\u2082 \u2014 making cars more environmentally friendly overall", false], ["They add oxygen to the exhaust to ensure complete combustion of any remaining fuel", false]], "q": "How do catalytic converters reduce air pollution from cars?", "wrong_explanations": {"1": "Particulate filters are separate devices \u2014 catalytic converters work by CHEMICAL REACTIONS, not filtration.", "2": "Catalytic converters actually INCREASE CO\u2082 (by converting CO to CO\u2082). They do NOT reduce CO\u2082 emissions.", "3": "Catalysts work by providing alternative reaction pathways \u2014 they don't inject additional oxygen into the exhaust."}}], "TH": [{"opts": [["CO binds irreversibly to haemoglobin \u2014 preventing red blood cells from carrying oxygen, causing suffocation even in small concentrations", true], ["CO is a coloured gas \u2014 it can be detected visually, making it more alarming", false], ["CO is heavier than air \u2014 it sinks and accumulates at floor level where people breathe", false], ["CO reacts with water in the lungs to form carbonic acid", false]], "q": "Why is carbon monoxide (CO) particularly dangerous compared to carbon dioxide (CO\u2082)?", "wrong_explanations": {"1": "CO is COLOURLESS and ODOURLESS \u2014 this makes it MORE dangerous as it cannot be detected by sight or smell without a detector.", "2": "CO has a density very similar to air \u2014 it doesn't strongly stratify, unlike some heavier gases.", "3": "CO does not react with water to form carbonic acid \u2014 that reaction is for CO\u2082. CO reacts with haemoglobin."}}, {"opts": [["They convert toxic CO and NO\u2093 to CO\u2082 and N\u2082 using platinum and rhodium catalysts", true], ["They filter out solid particulates using a fine mesh \u2014 trapping soot before it leaves the exhaust", false], ["They reduce all emissions including CO\u2082 \u2014 making cars more environmentally friendly overall", false], ["They add oxygen to the exhaust to ensure complete combustion of any remaining fuel", false]], "q": "How do catalytic converters reduce air pollution from cars?", "wrong_explanations": {"1": "Particulate filters are separate devices \u2014 catalytic converters work by CHEMICAL REACTIONS, not filtration.", "2": "Catalytic converters actually INCREASE CO\u2082 (by converting CO to CO\u2082). They do NOT reduce CO\u2082 emissions.", "3": "Catalysts work by providing alternative reaction pathways \u2014 they don't inject additional oxygen into the exhaust."}}]}, "summary": "Describe the pollutants produced by burning fuels and their effects on health and environment.", "theory": [{"content": "Burning FOSSIL FUELS releases several POLLUTANTS in addition to CO\u2082 and water:\n\nCARBON MONOXIDE (CO):\nFrom INCOMPLETE COMBUSTION \u2014 insufficient oxygen.\nCOLOURLESS, ODOURLESS, TOXIC gas.\nBinds to haemoglobin in red blood cells \u2014 prevents oxygen transport \u2192 can be fatal.\nMeasured by CO detectors in homes.\n\nSULFUR DIOXIDE (SO\u2082):\nFuels contain sulfur impurities \u2192 S + O\u2082 \u2192 SO\u2082 when burned.\nCauses ACID RAIN when SO\u2082 reacts with water and oxygen in the atmosphere:\nSO\u2082 + H\u2082O \u2192 H\u2082SO\u2083 (sulfurous acid) / SO\u2083 + H\u2082O \u2192 H\u2082SO\u2084 (sulfuric acid)\nACID RAIN effects: damages buildings/statues (limestone dissolves), kills trees, acidifies lakes killing fish.\nAlso causes respiratory problems \u2014 irritates airways.\n\nNITROGEN OXIDES (NO\u2093 \u2014 mainly NO and NO\u2082):\nProduced when N\u2082 and O\u2082 from air react at the high temperatures inside engines:\nN\u2082 + O\u2082 \u2192 2NO \u2192 oxidised to NO\u2082\nNO\u2093 also causes ACID RAIN (nitric acid).\nContributes to SMOG and LOW-LEVEL OZONE (O\u2083) which irritates lungs.\n\nPARTICULATES (soot/carbon particles):\nFrom incomplete combustion of fuels.\nVery small particles that penetrate deep into lungs.\nCause respiratory disease, aggravate asthma.\nConsciously contribute to GLOBAL DIMMING \u2014 reducing sunlight reaching Earth.", "heading": "Pollutants from Combustion of Fuels"}, {"content": "ACID RAIN forms when sulfur dioxide (SO\u2082) and nitrogen oxides (NO\u2093) dissolve in rainwater:\n\nFORMATION:\nSO\u2082 + H\u2082O + \u00bdO\u2082 \u2192 H\u2082SO\u2084 (sulfuric acid)\n4NO\u2082 + O\u2082 + 2H\u2082O \u2192 4HNO\u2083 (nitric acid)\n\nNormal rain is slightly acidic (pH ~5.6) due to dissolved CO\u2082.\nAcid rain: pH typically 4\u20135 \u2014 10\u00d7 to 100\u00d7 more acidic than normal rain.\n\nEFFECTS:\nBUILDINGS AND STATUES: dissolves limestone and marble:\nCaCO\u2083 + H\u2082SO\u2084 \u2192 CaSO\u2084 + H\u2082O + CO\u2082\nIrreplaceable historical buildings damaged.\n\nECOSYSTEMS:\nLakes and rivers become too acidic for aquatic life \u2014 fish die.\nSoil acidification \u2192 releases toxic aluminium ions \u2192 kills trees.\nForest die-back in areas downwind of industrial zones.\n\nHUMAN HEALTH:\nSO\u2082 and NO\u2082 irritate respiratory system \u2014 worsen asthma, bronchitis.\n\nSOLUTIONS:\nREMOVE SULFUR from fuels before burning (desulfurisation).\nCATALYTIC CONVERTERS in cars \u2014 convert CO, NO\u2093 and unburned hydrocarbons to CO\u2082, N\u2082 and H\u2082O.\nSCRUBBERS in power station chimneys \u2014 spray calcium hydroxide to neutralise SO\u2082.", "heading": "Acid Rain \u2014 Causes and Effects"}, {"content": "CATALYTIC CONVERTERS convert toxic exhaust gases to less harmful ones:\n\nPLATINUM AND RHODIUM catalysts:\n2CO + 2NO \u2192 2CO\u2082 + N\u2082\n(toxic carbon monoxide + toxic nitrogen oxide \u2192 CO\u2082 + harmless nitrogen)\n\nAlso convert unburned hydrocarbons:\nHydrocarbon + O\u2082 \u2192 CO\u2082 + H\u2082O\n\nReduces: CO (toxic), NO\u2093 (acid rain, smog) and particulates.\nDoes NOT reduce CO\u2082 (a greenhouse gas) \u2014 actually increases CO\u2082 by converting CO to CO\u2082.\n\nOTHER SOLUTIONS:\nLOW-SULFUR FUELS \u2014 reduce SO\u2082 at source.\nPARTICULATE FILTERS in diesel vehicles.\nELECTRIC VEHICLES \u2014 no exhaust combustion pollutants (though power station emissions are a separate issue).\nIMPROVED ENGINE DESIGN \u2014 more complete combustion, less CO and particulates.\nINTERNATIONAL AGREEMENTS \u2014 e.g. limits on SO\u2082 emissions from power stations.", "heading": "Catalytic Converters and Reducing Pollution"}]};
window.KS4SRC["infrared-black-bodies"] = {"common_mistake": "A PERFECT BLACK BODY is black because it absorbs ALL radiation \u2014 it also emits MAXIMUM radiation for its temperature. Being a 'perfect emitter' and 'perfect absorber' go together. Hotter objects emit at SHORTER wavelengths \u2014 this seems counterintuitive but is why glowing objects change colour from red to white-hot as they get hotter.", "higher": "Explain black body radiation curves \u2014 how peak wavelength depends on temperature. Describe how Earth's radiation balance determines its temperature. Explain the greenhouse effect mechanistically. Evaluate how changes in albedo or greenhouse gas concentration affect Earth's temperature.", "key_note": "All objects emit and absorb IR. Dark matt = best emitter and absorber. Shiny = best reflector. Black body: absorbs all radiation, emits maximum for its temperature. Hotter \u2192 more emission at shorter wavelength. Stars: colour indicates temperature (red=cool, blue=hot). Earth absorbs solar, re-emits IR \u2014 greenhouse effect.", "matching": {"instruction": "Match each statement to the correct concept.", "pairs": [["Dark matt surface", "Best emitter and absorber of infrared radiation"], ["Perfect black body", "Absorbs all incident radiation \u2014 emits maximum radiation for its temperature"], ["Hotter object", "Emits more radiation AND at shorter wavelengths \u2014 peak shifts towards visible/UV"], ["Blue-white star", "Very hot (~30,000 K) \u2014 peak emission in UV/blue visible range"]], "title": "Infrared and Black Bodies"}, "quiz": {"TF": [{"opts": [["As temperature increases, the peak emission shifts to shorter wavelengths \u2014 from infrared through red to shorter visible wavelengths approaching white", true], ["The metal changes chemical composition as it gets hotter, producing different coloured oxides", false], ["Different wavelengths of light are produced by different electrons in the metal", false], ["White light contains all colours \u2014 the metal must be emitting all wavelengths at low temperature but only red at high temperature", false]], "q": "A metal rod is heated in a furnace. First it glows red, then orange, then white. What does this tell us?", "wrong_explanations": {"1": "The colour change is due to temperature-dependent emission spectra \u2014 not chemical changes. A pure metal rod would show the same progression.", "2": "Different electrons in the metal contribute to emission, but the pattern follows the temperature-dependent black body spectrum \u2014 the overall colour shift is about temperature.", "3": "White hot means the peak has moved to visible wavelengths with broad-spectrum emission \u2014 cool objects emit IR (invisible) then progress through red, orange, yellow to white as temperature rises."}}, {"opts": [["Silvered walls are poor emitters and poor absorbers of infrared \u2014 they reflect radiation back, reducing thermal energy transfer by radiation", true], ["Silver is a good conductor \u2014 it rapidly distributes heat evenly around the flask walls", false], ["Silver reacts with oxygen in the air \u2014 the oxide layer acts as an insulator", false], ["The bright colour of silver reflects external light, keeping the flask cool", false]], "q": "Why are the walls of a thermos flask silvered?", "wrong_explanations": {"1": "Silver is an excellent conductor \u2014 but the silvered wall is there to REDUCE radiation transfer, not to conduct heat.", "2": "Silver doesn't form a significant protective oxide layer at room temperature \u2014 the silvering works by reflection of radiation.", "3": "Visible light reflection is not the primary reason \u2014 it's the IR radiation reflection that reduces thermal energy transfer."}}], "TH": [{"opts": [["As temperature increases, the peak emission shifts to shorter wavelengths \u2014 from infrared through red to shorter visible wavelengths approaching white", true], ["The metal changes chemical composition as it gets hotter, producing different coloured oxides", false], ["Different wavelengths of light are produced by different electrons in the metal", false], ["White light contains all colours \u2014 the metal must be emitting all wavelengths at low temperature but only red at high temperature", false]], "q": "A metal rod is heated in a furnace. First it glows red, then orange, then white. What does this tell us?", "wrong_explanations": {"1": "The colour change is due to temperature-dependent emission spectra \u2014 not chemical changes. A pure metal rod would show the same progression.", "2": "Different electrons in the metal contribute to emission, but the pattern follows the temperature-dependent black body spectrum \u2014 the overall colour shift is about temperature.", "3": "White hot means the peak has moved to visible wavelengths with broad-spectrum emission \u2014 cool objects emit IR (invisible) then progress through red, orange, yellow to white as temperature rises."}}, {"opts": [["Silvered walls are poor emitters and poor absorbers of infrared \u2014 they reflect radiation back, reducing thermal energy transfer by radiation", true], ["Silver is a good conductor \u2014 it rapidly distributes heat evenly around the flask walls", false], ["Silver reacts with oxygen in the air \u2014 the oxide layer acts as an insulator", false], ["The bright colour of silver reflects external light, keeping the flask cool", false]], "q": "Why are the walls of a thermos flask silvered?", "wrong_explanations": {"1": "Silver is an excellent conductor \u2014 but the silvered wall is there to REDUCE radiation transfer, not to conduct heat.", "2": "Silver doesn't form a significant protective oxide layer at room temperature \u2014 the silvering works by reflection of radiation.", "3": "Visible light reflection is not the primary reason \u2014 it's the IR radiation reflection that reduces thermal energy transfer."}}]}, "summary": "Describe infrared emission and absorption by surfaces and explain perfect black body radiation.", "theory": [{"content": "All objects emit and absorb THERMAL RADIATION (infrared radiation) continuously.\n\nEMISSION:\nAll objects above absolute zero emit infrared radiation.\nHotter objects emit MORE radiation and at SHORTER wavelengths (higher frequency, more energetic).\n\nABSORPTION:\nObjects absorb radiation from their surroundings.\nDark, matt surfaces are better ABSORBERS than light, shiny surfaces.\n\nDark matt surfaces are also better EMITTERS.\nShiny, light surfaces are better REFLECTORS and poorer emitters/absorbers.\n\nEMISSION vs ABSORPTION RATES:\nIf emission rate > absorption rate \u2192 object cools.\nIf absorption rate > emission rate \u2192 object heats up.\nIf rates are equal \u2192 temperature is constant (thermal equilibrium).", "heading": "Emission and Absorption of Radiation"}, {"content": "A PERFECT BLACK BODY is a theoretical object that:\nABSORBS all radiation that falls on it (reflects none).\nEMITS the maximum amount of radiation for its temperature.\n\nPerfect black bodies emit the most radiation of any object at the same temperature.\nThe emission spectrum of a black body depends ONLY on temperature \u2014 not on the material.\n\nBLACK BODY RADIATION CURVES:\nAs temperature increases:\nPeak of emission shifts to SHORTER wavelengths (higher frequency).\nTotal energy emitted per second INCREASES dramatically.\n\nEXAMPLE:\nA cool object: emits mainly low-frequency infrared \u2014 invisible to the eye.\nHot iron (600\u00b0C): glows dull red \u2014 emitting visible red light.\nVery hot iron (1000\u00b0C): orange-white \u2014 peak moves into visible range.\nThe Sun (~5500\u00b0C surface): peak emission in visible light (yellow-green).\n\nA cavity with a small hole acts as an approximate black body.", "heading": "Perfect Black Bodies"}, {"content": "STARS AS BLACK BODIES:\nStars approximately behave as black bodies.\nThe colour of a star indicates its surface temperature:\nRed stars (~3000 K) \u2192 cool \u2192 peak in infrared/red.\nYellow stars (like the Sun, ~5500 K) \u2192 medium \u2192 peak in visible.\nBlue-white stars (~30,000 K) \u2192 very hot \u2192 peak in UV/blue.\n\nEARTH'S TEMPERATURE:\nThe Earth absorbs solar radiation and re-emits as infrared (longer wavelength \u2014 Earth is cooler than Sun).\nGreenhouse gases absorb Earth's infrared emission \u2192 trap energy \u2192 warming effect.\n\nTHERMAL CAMERAS:\nDetect infrared emitted by warm objects \u2014 used in: night vision, firefighting, medical diagnosis (detecting hot spots), building inspection (heat loss).\n\nSPACE TELESCOPES:\nInfrared telescopes detect emission from cool objects like dust clouds in space.\nHubble detects visible light; James Webb Space Telescope detects infrared.\n\nSELECTIVE EMISSION AND ABSORPTION:\nSolar panels: dark, matt surfaces to maximise solar absorption.\nSolar water heaters: black tubes to maximise absorption.\nThermos flasks: silvered walls to minimise emission and absorption (reflect radiation back).", "heading": "Applications"}]};
window.KS4SRC["transport-in-cells"] = {"common_mistake": "Osmosis involves WATER ONLY \u2014 through a PARTIALLY PERMEABLE MEMBRANE. Glucose, ions and other molecules do NOT move by osmosis. Active transport goes AGAINST the gradient and requires ATP energy \u2014 without ATP (no respiration) it stops. Diffusion and osmosis are both PASSIVE \u2014 no ATP needed. Never say 'diffusion requires energy'.", "fifas": [{"label": "Osmosis \u2014 Percentage Change in Mass", "question": "A potato cylinder has a mass of 4.0 g before being placed in a concentrated sugar solution. After 30 minutes it has a mass of 3.4 g. Calculate the percentage change in mass.", "steps": [["F", "% change = (final mass \u2212 initial mass) \u00f7 initial mass \u00d7 100"], ["I", "% change = (3.4 \u2212 4.0) \u00f7 4.0 \u00d7 100"], ["F", "= (\u22120.6) \u00f7 4.0 \u00d7 100 = \u221215%"], ["A", "% change = \u221215% (a decrease \u2014 water left by osmosis into the concentrated solution)"]]}], "higher": "Calculating percentage change in mass in osmosis: % change = (change in mass \u00f7 original mass) \u00d7 100. The isotonic point \u2014 where a plant tissue neither gains nor loses mass \u2014 is where the external solution concentration matches the cell's water potential. Exchange surfaces are adapted with large surface area, thin walls, good blood supply/ventilation. Students should be able to explain and calculate surface area to volume ratios and explain why large organisms need exchange systems.", "key_note": "Diffusion: particles, high \u2192 low, passive. Osmosis: water only, dilute \u2192 concentrated, partially permeable membrane, passive. Active transport: low \u2192 high, against gradient, requires ATP + carrier proteins.", "matching": {"instruction": "Match each description to diffusion, osmosis or active transport.", "pairs": [["Diffusion", "Net movement of particles from high to low concentration \u2014 no energy needed"], ["Osmosis", "Movement of water molecules only across a partially permeable membrane \u2014 passive"], ["Active transport", "Movement against the concentration gradient \u2014 requires ATP and carrier proteins"], ["Diffusion", "Oxygen moving from alveoli into the blood \u2014 no ATP required"], ["Osmosis", "Water entering a root hair cell from the soil \u2014 the soil water is more dilute than cell contents"], ["Active transport", "Mineral ions absorbed into root hair cells from dilute soil water \u2014 against the gradient"]], "title": "Match the Transport Process"}, "quiz": {"CF": [{"opts": [["Active transport", true], ["Diffusion", false], ["Osmosis", false], ["Both diffusion and osmosis", false]], "q": "Which process requires ATP energy to move substances across a cell membrane?", "wrong_explanations": {"1": "Diffusion is PASSIVE \u2014 particles move due to their own random kinetic energy, not ATP.", "2": "Osmosis is also PASSIVE \u2014 water moves down its own concentration gradient without energy input.", "3": "NEITHER diffusion nor osmosis requires ATP. Only active transport requires energy \u2014 that is what distinguishes it from the other two."}}, {"opts": [["It gains mass \u2014 water enters by osmosis from the dilute water into the more concentrated cell contents", true], ["It loses mass \u2014 salt leaves the potato into the water by diffusion", false], ["Nothing \u2014 the potato is not permeable to water", false], ["It gains mass because water enters by active transport", false]], "q": "A potato cylinder is placed in pure water. What happens and why?", "wrong_explanations": {"1": "Salt does diffuse slightly \u2014 but the dominant effect is water moving by OSMOSIS into the cells, increasing mass.", "2": "Cell membranes are selectively permeable \u2014 water moves freely across them by osmosis. The potato is very much permeable to water.", "3": "Osmosis is PASSIVE \u2014 it requires no energy input. Water moves down its concentration gradient automatically."}}, {"opts": [["No oxygen \u2192 aerobic respiration stops \u2192 no ATP produced \u2192 no energy for active transport", true], ["Oxygen is a carrier protein that directly powers active transport", false], ["Without oxygen, the cell membrane becomes impermeable to all substances", false], ["Removing oxygen changes the concentration gradient, making active transport unnecessary", false]], "q": "Why does active transport stop if oxygen is removed from the environment of a cell?", "wrong_explanations": {"1": "Oxygen doesn't directly power carrier proteins \u2014 it is needed for aerobic respiration to produce ATP, which then powers the carriers.", "2": "Membranes remain structurally intact without oxygen \u2014 it is the ATP supply that is lost, not membrane structure.", "3": "Removing oxygen doesn't change concentration gradients. It removes the ATP supply needed to pump substances against those gradients."}}, {"opts": [["Water leaves by osmosis \u2192 the cell becomes flaccid \u2192 the cell membrane pulls away from the cell wall (plasmolysis)", true], ["Water enters by osmosis \u2192 the cell becomes turgid and very firm", false], ["Salt enters by active transport \u2192 the cell becomes denser", false], ["The cell bursts because it cannot handle the osmotic pressure", false]], "q": "A plant cell is placed in a very concentrated salt solution. What will happen?", "wrong_explanations": {"1": "Water enters when the EXTERNAL solution is MORE DILUTE than the cell contents. In concentrated salt solution, it is the other way round \u2014 water leaves.", "2": "Salt ions may slowly diffuse in, but the dominant effect is OSMOSIS \u2014 water moves to the MORE CONCENTRATED solution (the salt solution outside), not into the cell.", "3": "Plant cells have a rigid CELL WALL that prevents bursting \u2014 unlike animal cells. A plant cell can become flaccid or plasmolyse, but it won't burst."}}, {"opts": [["The net movement of water molecules across a partially permeable membrane from a dilute solution to a more concentrated solution", true], ["The movement of any particles from high to low concentration \u2014 passive", false], ["The movement of water molecules against a concentration gradient using ATP", false], ["The diffusion of water molecules through any membrane in any direction", false]], "q": "What is the definition of osmosis?", "wrong_explanations": {"1": "The movement of ANY particles from high to low = DIFFUSION. Osmosis is specifically about WATER ONLY through a PARTIALLY PERMEABLE membrane.", "2": "Movement against a gradient using ATP = ACTIVE TRANSPORT. Osmosis is passive \u2014 water moves DOWN its concentration gradient.", "3": "Osmosis only occurs through a PARTIALLY PERMEABLE membrane, not any membrane. And it only moves water in ONE net direction \u2014 from dilute to concentrated."}}], "CH": [{"opts": [["Active transport", true], ["Diffusion", false], ["Osmosis", false], ["Both diffusion and osmosis", false]], "q": "Which process requires ATP energy to move substances across a cell membrane?", "wrong_explanations": {"1": "Diffusion is PASSIVE \u2014 particles move due to their own random kinetic energy, not ATP.", "2": "Osmosis is also PASSIVE \u2014 water moves down its own concentration gradient without energy input.", "3": "NEITHER diffusion nor osmosis requires ATP. Only active transport requires energy \u2014 that is what distinguishes it from the other two."}}, {"opts": [["It gains mass \u2014 water enters by osmosis from the dilute water into the more concentrated cell contents", true], ["It loses mass \u2014 salt leaves the potato into the water by diffusion", false], ["Nothing \u2014 the potato is not permeable to water", false], ["It gains mass because water enters by active transport", false]], "q": "A potato cylinder is placed in pure water. What happens and why?", "wrong_explanations": {"1": "Salt does diffuse slightly \u2014 but the dominant effect is water moving by OSMOSIS into the cells, increasing mass.", "2": "Cell membranes are selectively permeable \u2014 water moves freely across them by osmosis. The potato is very much permeable to water.", "3": "Osmosis is PASSIVE \u2014 it requires no energy input. Water moves down its concentration gradient automatically."}}, {"opts": [["No oxygen \u2192 aerobic respiration stops \u2192 no ATP produced \u2192 no energy for active transport", true], ["Oxygen is a carrier protein that directly powers active transport", false], ["Without oxygen, the cell membrane becomes impermeable to all substances", false], ["Removing oxygen changes the concentration gradient, making active transport unnecessary", false]], "q": "Why does active transport stop if oxygen is removed from the environment of a cell?", "wrong_explanations": {"1": "Oxygen doesn't directly power carrier proteins \u2014 it is needed for aerobic respiration to produce ATP, which then powers the carriers.", "2": "Membranes remain structurally intact without oxygen \u2014 it is the ATP supply that is lost, not membrane structure.", "3": "Removing oxygen doesn't change concentration gradients. It removes the ATP supply needed to pump substances against those gradients."}}, {"opts": [["Water leaves by osmosis \u2192 the cell becomes flaccid \u2192 the cell membrane pulls away from the cell wall (plasmolysis)", true], ["Water enters by osmosis \u2192 the cell becomes turgid and very firm", false], ["Salt enters by active transport \u2192 the cell becomes denser", false], ["The cell bursts because it cannot handle the osmotic pressure", false]], "q": "A plant cell is placed in a very concentrated salt solution. What will happen?", "wrong_explanations": {"1": "Water enters when the EXTERNAL solution is MORE DILUTE than the cell contents. In concentrated salt solution, it is the other way round \u2014 water leaves.", "2": "Salt ions may slowly diffuse in, but the dominant effect is OSMOSIS \u2014 water moves to the MORE CONCENTRATED solution (the salt solution outside), not into the cell.", "3": "Plant cells have a rigid CELL WALL that prevents bursting \u2014 unlike animal cells. A plant cell can become flaccid or plasmolyse, but it won't burst."}}, {"opts": [["The net movement of water molecules across a partially permeable membrane from a dilute solution to a more concentrated solution", true], ["The movement of any particles from high to low concentration \u2014 passive", false], ["The movement of water molecules against a concentration gradient using ATP", false], ["The diffusion of water molecules through any membrane in any direction", false]], "q": "What is the definition of osmosis?", "wrong_explanations": {"1": "The movement of ANY particles from high to low = DIFFUSION. Osmosis is specifically about WATER ONLY through a PARTIALLY PERMEABLE membrane.", "2": "Movement against a gradient using ATP = ACTIVE TRANSPORT. Osmosis is passive \u2014 water moves DOWN its concentration gradient.", "3": "Osmosis only occurs through a PARTIALLY PERMEABLE membrane, not any membrane. And it only moves water in ONE net direction \u2014 from dilute to concentrated."}}], "TF": [{"opts": [["Active transport", true], ["Diffusion", false], ["Osmosis", false], ["Both diffusion and osmosis", false]], "q": "Which process requires ATP energy to move substances across a cell membrane?", "wrong_explanations": {"1": "Diffusion is PASSIVE \u2014 particles move due to their own random kinetic energy, not ATP.", "2": "Osmosis is also PASSIVE \u2014 water moves down its own concentration gradient without energy input.", "3": "NEITHER diffusion nor osmosis requires ATP. Only active transport requires energy \u2014 that is what distinguishes it from the other two."}}, {"opts": [["It gains mass \u2014 water enters by osmosis from the dilute water into the more concentrated cell contents", true], ["It loses mass \u2014 salt leaves the potato into the water by diffusion", false], ["Nothing \u2014 the potato is not permeable to water", false], ["It gains mass because water enters by active transport", false]], "q": "A potato cylinder is placed in pure water. What happens and why?", "wrong_explanations": {"1": "Salt does diffuse slightly \u2014 but the dominant effect is water moving by OSMOSIS into the cells, increasing mass.", "2": "Cell membranes are selectively permeable \u2014 water moves freely across them by osmosis. The potato is very much permeable to water.", "3": "Osmosis is PASSIVE \u2014 it requires no energy input. Water moves down its concentration gradient automatically."}}, {"opts": [["No oxygen \u2192 aerobic respiration stops \u2192 no ATP produced \u2192 no energy for active transport", true], ["Oxygen is a carrier protein that directly powers active transport", false], ["Without oxygen, the cell membrane becomes impermeable to all substances", false], ["Removing oxygen changes the concentration gradient, making active transport unnecessary", false]], "q": "Why does active transport stop if oxygen is removed from the environment of a cell?", "wrong_explanations": {"1": "Oxygen doesn't directly power carrier proteins \u2014 it is needed for aerobic respiration to produce ATP, which then powers the carriers.", "2": "Membranes remain structurally intact without oxygen \u2014 it is the ATP supply that is lost, not membrane structure.", "3": "Removing oxygen doesn't change concentration gradients. It removes the ATP supply needed to pump substances against those gradients."}}, {"opts": [["Water leaves by osmosis \u2192 the cell becomes flaccid \u2192 the cell membrane pulls away from the cell wall (plasmolysis)", true], ["Water enters by osmosis \u2192 the cell becomes turgid and very firm", false], ["Salt enters by active transport \u2192 the cell becomes denser", false], ["The cell bursts because it cannot handle the osmotic pressure", false]], "q": "A plant cell is placed in a very concentrated salt solution. What will happen?", "wrong_explanations": {"1": "Water enters when the EXTERNAL solution is MORE DILUTE than the cell contents. In concentrated salt solution, it is the other way round \u2014 water leaves.", "2": "Salt ions may slowly diffuse in, but the dominant effect is OSMOSIS \u2014 water moves to the MORE CONCENTRATED solution (the salt solution outside), not into the cell.", "3": "Plant cells have a rigid CELL WALL that prevents bursting \u2014 unlike animal cells. A plant cell can become flaccid or plasmolyse, but it won't burst."}}, {"opts": [["The net movement of water molecules across a partially permeable membrane from a dilute solution to a more concentrated solution", true], ["The movement of any particles from high to low concentration \u2014 passive", false], ["The movement of water molecules against a concentration gradient using ATP", false], ["The diffusion of water molecules through any membrane in any direction", false]], "q": "What is the definition of osmosis?", "wrong_explanations": {"1": "The movement of ANY particles from high to low = DIFFUSION. Osmosis is specifically about WATER ONLY through a PARTIALLY PERMEABLE membrane.", "2": "Movement against a gradient using ATP = ACTIVE TRANSPORT. Osmosis is passive \u2014 water moves DOWN its concentration gradient.", "3": "Osmosis only occurs through a PARTIALLY PERMEABLE membrane, not any membrane. And it only moves water in ONE net direction \u2014 from dilute to concentrated."}}], "TH": [{"opts": [["Active transport", true], ["Diffusion", false], ["Osmosis", false], ["Both diffusion and osmosis", false]], "q": "Which process requires ATP energy to move substances across a cell membrane?", "wrong_explanations": {"1": "Diffusion is PASSIVE \u2014 particles move due to their own random kinetic energy, not ATP.", "2": "Osmosis is also PASSIVE \u2014 water moves down its own concentration gradient without energy input.", "3": "NEITHER diffusion nor osmosis requires ATP. Only active transport requires energy \u2014 that is what distinguishes it from the other two."}}, {"opts": [["It gains mass \u2014 water enters by osmosis from the dilute water into the more concentrated cell contents", true], ["It loses mass \u2014 salt leaves the potato into the water by diffusion", false], ["Nothing \u2014 the potato is not permeable to water", false], ["It gains mass because water enters by active transport", false]], "q": "A potato cylinder is placed in pure water. What happens and why?", "wrong_explanations": {"1": "Salt does diffuse slightly \u2014 but the dominant effect is water moving by OSMOSIS into the cells, increasing mass.", "2": "Cell membranes are selectively permeable \u2014 water moves freely across them by osmosis. The potato is very much permeable to water.", "3": "Osmosis is PASSIVE \u2014 it requires no energy input. Water moves down its concentration gradient automatically."}}, {"opts": [["No oxygen \u2192 aerobic respiration stops \u2192 no ATP produced \u2192 no energy for active transport", true], ["Oxygen is a carrier protein that directly powers active transport", false], ["Without oxygen, the cell membrane becomes impermeable to all substances", false], ["Removing oxygen changes the concentration gradient, making active transport unnecessary", false]], "q": "Why does active transport stop if oxygen is removed from the environment of a cell?", "wrong_explanations": {"1": "Oxygen doesn't directly power carrier proteins \u2014 it is needed for aerobic respiration to produce ATP, which then powers the carriers.", "2": "Membranes remain structurally intact without oxygen \u2014 it is the ATP supply that is lost, not membrane structure.", "3": "Removing oxygen doesn't change concentration gradients. It removes the ATP supply needed to pump substances against those gradients."}}, {"opts": [["Water leaves by osmosis \u2192 the cell becomes flaccid \u2192 the cell membrane pulls away from the cell wall (plasmolysis)", true], ["Water enters by osmosis \u2192 the cell becomes turgid and very firm", false], ["Salt enters by active transport \u2192 the cell becomes denser", false], ["The cell bursts because it cannot handle the osmotic pressure", false]], "q": "A plant cell is placed in a very concentrated salt solution. What will happen?", "wrong_explanations": {"1": "Water enters when the EXTERNAL solution is MORE DILUTE than the cell contents. In concentrated salt solution, it is the other way round \u2014 water leaves.", "2": "Salt ions may slowly diffuse in, but the dominant effect is OSMOSIS \u2014 water moves to the MORE CONCENTRATED solution (the salt solution outside), not into the cell.", "3": "Plant cells have a rigid CELL WALL that prevents bursting \u2014 unlike animal cells. A plant cell can become flaccid or plasmolyse, but it won't burst."}}, {"opts": [["The net movement of water molecules across a partially permeable membrane from a dilute solution to a more concentrated solution", true], ["The movement of any particles from high to low concentration \u2014 passive", false], ["The movement of water molecules against a concentration gradient using ATP", false], ["The diffusion of water molecules through any membrane in any direction", false]], "q": "What is the definition of osmosis?", "wrong_explanations": {"1": "The movement of ANY particles from high to low = DIFFUSION. Osmosis is specifically about WATER ONLY through a PARTIALLY PERMEABLE membrane.", "2": "Movement against a gradient using ATP = ACTIVE TRANSPORT. Osmosis is passive \u2014 water moves DOWN its concentration gradient.", "3": "Osmosis only occurs through a PARTIALLY PERMEABLE membrane, not any membrane. And it only moves water in ONE net direction \u2014 from dilute to concentrated."}}]}, "rp": "RP2 \u2014 Investigate osmosis: place potato cylinders in different concentrations of sucrose solution. Measure mass before and after. Calculate % change in mass.", "summary": "Describe and compare the three ways substances move into and out of cells.", "theory": [{"content": "DIFFUSION is the net movement of particles (molecules or ions) from a region of HIGHER concentration to a region of LOWER concentration \u2014 down the concentration gradient.\nIt is a PASSIVE process \u2014 no energy (ATP) is required. Particles move due to their own random kinetic energy.\nDiffusion continues until concentrations are equal on both sides \u2014 this is called EQUILIBRIUM. Even at equilibrium, particles are still moving randomly \u2014 there's just no NET movement.\n\nFactors that increase the rate of diffusion:\n\u2022 STEEPER concentration gradient \u2014 bigger difference in concentration = faster net movement\n\u2022 HIGHER temperature \u2014 more kinetic energy \u2192 particles move faster\n\u2022 LARGER surface area \u2014 more space available for diffusion to occur across\n\u2022 SHORTER diffusion distance \u2014 thinner membrane \u2192 particles cross faster\n\nExamples in biology:\n\u2022 O\u2082 diffuses from alveoli (high [O\u2082]) \u2192 into blood (lower [O\u2082]) \u2192 into muscle cells (even lower [O\u2082])\n\u2022 CO\u2082 diffuses from respiring cells (high [CO\u2082]) \u2192 into blood \u2192 into alveoli (low [CO\u2082])\n\u2022 Glucose diffuses from the small intestine (high [glucose] after digestion) \u2192 into blood\n\u2022 Urea diffuses from liver cells (where it is made) \u2192 into blood \u2192 into kidney tubules \u2192 excreted in urine", "heading": "Diffusion"}, {"content": "OSMOSIS is a special type of diffusion \u2014 it is the net movement of WATER MOLECULES ONLY across a PARTIALLY PERMEABLE MEMBRANE, from a DILUTE solution (more water molecules, high water potential) to a MORE CONCENTRATED solution (fewer water molecules, low water potential).\nA partially permeable membrane has tiny pores that allow small water molecules through but block larger solute molecules.\nOsmosis is also PASSIVE \u2014 no ATP energy is required.\n\nIn PLANT CELLS:\n\u2022 Cell placed in DILUTE solution: water enters by osmosis \u2192 vacuole swells \u2192 cell membrane pushes against rigid cell wall \u2192 cell becomes TURGID (firm). Turgid cells provide structural support to the plant.\n\u2022 Cell placed in CONCENTRATED solution: water leaves by osmosis \u2192 vacuole and cytoplasm shrink \u2192 cell membrane pulls away from cell wall \u2192 PLASMOLYSIS. Plant wilts.\n\nIn ANIMAL CELLS (no cell wall to limit swelling):\n\u2022 Cell in DILUTE solution: water enters by osmosis \u2192 cell SWELLS \u2192 may BURST (LYSIS) if too much water enters \u2014 e.g. red blood cells burst in pure water\n\u2022 Cell in CONCENTRATED solution: water leaves by osmosis \u2192 cell SHRINKS (CRENATION)\nThis is why the body carefully controls the concentration of blood and body fluids \u2014 deviations cause serious damage to cells.", "heading": "Osmosis"}, {"content": "ACTIVE TRANSPORT is the movement of substances from a region of LOWER concentration to a region of HIGHER concentration \u2014 AGAINST the concentration gradient.\nThis requires:\n1. ENERGY from ATP (produced by aerobic respiration)\n2. CARRIER PROTEINS embedded in the cell membrane\nBecause it requires ATP, active transport STOPS immediately if respiration is blocked (e.g. by cyanide, which blocks aerobic respiration, or by removing oxygen).\n\nExamples in biology:\n\u2022 ROOTS absorbing minerals: the concentration of mineral ions (e.g. nitrates, magnesium) inside root hair cells is ALREADY HIGHER than in the soil water. Yet plants need even more. Active transport pumps them in against the gradient.\n\u2022 SMALL INTESTINE absorbing glucose: once most glucose has been absorbed by diffusion, the remaining glucose must be moved from the gut (low [glucose]) into the blood (higher [glucose]) by active transport \u2014 ensuring all available glucose is absorbed.", "heading": "Active Transport"}, {"content": "Single-celled organisms have a high surface area to volume ratio \u2014 simple diffusion is sufficient.\nLarge multicellular organisms have a much LOWER surface area to volume ratio \u2014 the distance from surface to interior cells is too great for diffusion alone.\nThey need SPECIALISED EXCHANGE SURFACES and TRANSPORT SYSTEMS.\n\nFeatures of an efficient exchange surface:\n\u2022 LARGE SURFACE AREA: more area for particles to cross per unit time\n\u2022 THIN MEMBRANE: short diffusion path\n\u2022 STEEP CONCENTRATION GRADIENT: maintained by good blood supply (or ventilation for gas exchange)\n\nExamples:\n\u2022 ALVEOLI (lungs): surrounded by dense capillary network, one cell thick, highly folded \u2014 for O\u2082/CO\u2082 exchange\n\u2022 VILLI (small intestine): finger-like projections with microvilli (brush border), rich blood supply, one cell thick walls \u2014 for nutrient absorption\n\u2022 ROOT HAIR CELLS: long projections increase surface area enormously \u2014 for water and mineral absorption from soil", "heading": "Exchange Surfaces in Multicellular Organisms"}]};
window.KS4SRC["blood"] = {"common_mistake": "Red blood cells carry oxygen \u2014 white blood cells do NOT carry oxygen. White blood cells fight infection. Platelets are NOT cells \u2014 they are cell fragments with no nucleus. They are involved in clotting, NOT in carrying oxygen or fighting infection.", "key_note": "Red blood cells: O\u2082 transport, haemoglobin, no nucleus, biconcave. White blood cells: immune defence \u2014 phagocytes engulf, lymphocytes make antibodies. Platelets: clotting. Plasma: liquid transport medium.", "matching": {"instruction": "Match each blood component to its primary role.", "pairs": [["Red blood cells", "Carry oxygen using haemoglobin \u2014 biconcave disc, no nucleus"], ["Phagocytes", "Engulf and destroy pathogens \u2014 non-specific immune defence"], ["Lymphocytes", "Produce specific antibodies that match pathogen antigens"], ["Platelets", "Involved in blood clotting \u2014 form a fibrin mesh to seal wounds"], ["Plasma", "Liquid that transports glucose, CO\u2082, urea, hormones and heat"]], "title": "Match the Blood Component to its Function"}, "quiz": {"CF": [{"opts": [["To create more space for haemoglobin \u2014 allowing the cell to carry more oxygen", true], ["So they can divide and replace themselves when worn out", false], ["To reduce their weight so they flow faster through blood vessels", false], ["So they can squeeze through capillaries more easily", false]], "q": "Why do red blood cells have no nucleus?", "wrong_explanations": {"1": "Cells without a nucleus CANNOT divide \u2014 red blood cells are produced in bone marrow and cannot reproduce themselves.", "2": "Weight difference between a nucleus and haemoglobin molecules is negligible \u2014 the primary reason is space for haemoglobin.", "3": "Flexibility helps red blood cells squeeze through capillaries \u2014 but this is a result of their biconcave shape and flexibility, not the absence of a nucleus."}}, {"opts": [["Unable to produce specific antibodies \u2014 prolonged or repeated infections that are hard to clear", true], ["Unable to carry oxygen \u2014 severe anaemia", false], ["Blood will not clot properly \u2014 excessive bleeding from wounds", false], ["Unable to digest food properly \u2014 nutrients not absorbed", false]], "q": "A patient has very few lymphocytes. What is the most likely consequence?", "wrong_explanations": {"1": "Oxygen carrying = RED BLOOD CELLS using haemoglobin. Lymphocytes are white blood cells.", "2": "Blood clotting = PLATELETS forming a fibrin mesh. Lymphocytes produce antibodies, not clotting factors.", "3": "Food digestion = digestive enzymes in the gut. Lymphocytes are part of the immune system."}}, {"opts": [["Blood clotting \u2014 they clump at wound sites and trigger fibrin mesh formation to seal the damage", true], ["Carrying oxygen from the lungs to body tissues", false], ["Producing antibodies to fight specific pathogens", false], ["Engulfing and digesting bacteria by phagocytosis", false]], "q": "What is the role of platelets in the body?", "wrong_explanations": {"1": "Oxygen transport = RED BLOOD CELLS using haemoglobin.", "2": "Producing antibodies = LYMPHOCYTES (a type of white blood cell).", "3": "Engulfing bacteria = PHAGOCYTES (a type of white blood cell)."}}, {"opts": [["Oxygen \u2014 this is carried by haemoglobin inside red blood cells", true], ["Glucose from the small intestine to body cells", false], ["Urea from the liver to the kidneys", false], ["Carbon dioxide from respiring cells to the lungs", false]], "q": "Which substance does plasma NOT transport?", "wrong_explanations": {"1": "Glucose IS carried in plasma \u2014 after absorption from the small intestine.", "2": "Urea IS carried in plasma \u2014 from the liver to the kidneys for excretion.", "3": "Carbon dioxide IS dissolved in plasma \u2014 most CO\u2082 travels as bicarbonate ions dissolved in plasma."}}], "CH": [{"opts": [["To create more space for haemoglobin \u2014 allowing the cell to carry more oxygen", true], ["So they can divide and replace themselves when worn out", false], ["To reduce their weight so they flow faster through blood vessels", false], ["So they can squeeze through capillaries more easily", false]], "q": "Why do red blood cells have no nucleus?", "wrong_explanations": {"1": "Cells without a nucleus CANNOT divide \u2014 red blood cells are produced in bone marrow and cannot reproduce themselves.", "2": "Weight difference between a nucleus and haemoglobin molecules is negligible \u2014 the primary reason is space for haemoglobin.", "3": "Flexibility helps red blood cells squeeze through capillaries \u2014 but this is a result of their biconcave shape and flexibility, not the absence of a nucleus."}}, {"opts": [["Unable to produce specific antibodies \u2014 prolonged or repeated infections that are hard to clear", true], ["Unable to carry oxygen \u2014 severe anaemia", false], ["Blood will not clot properly \u2014 excessive bleeding from wounds", false], ["Unable to digest food properly \u2014 nutrients not absorbed", false]], "q": "A patient has very few lymphocytes. What is the most likely consequence?", "wrong_explanations": {"1": "Oxygen carrying = RED BLOOD CELLS using haemoglobin. Lymphocytes are white blood cells.", "2": "Blood clotting = PLATELETS forming a fibrin mesh. Lymphocytes produce antibodies, not clotting factors.", "3": "Food digestion = digestive enzymes in the gut. Lymphocytes are part of the immune system."}}, {"opts": [["Blood clotting \u2014 they clump at wound sites and trigger fibrin mesh formation to seal the damage", true], ["Carrying oxygen from the lungs to body tissues", false], ["Producing antibodies to fight specific pathogens", false], ["Engulfing and digesting bacteria by phagocytosis", false]], "q": "What is the role of platelets in the body?", "wrong_explanations": {"1": "Oxygen transport = RED BLOOD CELLS using haemoglobin.", "2": "Producing antibodies = LYMPHOCYTES (a type of white blood cell).", "3": "Engulfing bacteria = PHAGOCYTES (a type of white blood cell)."}}, {"opts": [["Oxygen \u2014 this is carried by haemoglobin inside red blood cells", true], ["Glucose from the small intestine to body cells", false], ["Urea from the liver to the kidneys", false], ["Carbon dioxide from respiring cells to the lungs", false]], "q": "Which substance does plasma NOT transport?", "wrong_explanations": {"1": "Glucose IS carried in plasma \u2014 after absorption from the small intestine.", "2": "Urea IS carried in plasma \u2014 from the liver to the kidneys for excretion.", "3": "Carbon dioxide IS dissolved in plasma \u2014 most CO\u2082 travels as bicarbonate ions dissolved in plasma."}}], "TF": [{"opts": [["To create more space for haemoglobin \u2014 allowing the cell to carry more oxygen", true], ["So they can divide and replace themselves when worn out", false], ["To reduce their weight so they flow faster through blood vessels", false], ["So they can squeeze through capillaries more easily", false]], "q": "Why do red blood cells have no nucleus?", "wrong_explanations": {"1": "Cells without a nucleus CANNOT divide \u2014 red blood cells are produced in bone marrow and cannot reproduce themselves.", "2": "Weight difference between a nucleus and haemoglobin molecules is negligible \u2014 the primary reason is space for haemoglobin.", "3": "Flexibility helps red blood cells squeeze through capillaries \u2014 but this is a result of their biconcave shape and flexibility, not the absence of a nucleus."}}, {"opts": [["Unable to produce specific antibodies \u2014 prolonged or repeated infections that are hard to clear", true], ["Unable to carry oxygen \u2014 severe anaemia", false], ["Blood will not clot properly \u2014 excessive bleeding from wounds", false], ["Unable to digest food properly \u2014 nutrients not absorbed", false]], "q": "A patient has very few lymphocytes. What is the most likely consequence?", "wrong_explanations": {"1": "Oxygen carrying = RED BLOOD CELLS using haemoglobin. Lymphocytes are white blood cells.", "2": "Blood clotting = PLATELETS forming a fibrin mesh. Lymphocytes produce antibodies, not clotting factors.", "3": "Food digestion = digestive enzymes in the gut. Lymphocytes are part of the immune system."}}, {"opts": [["Blood clotting \u2014 they clump at wound sites and trigger fibrin mesh formation to seal the damage", true], ["Carrying oxygen from the lungs to body tissues", false], ["Producing antibodies to fight specific pathogens", false], ["Engulfing and digesting bacteria by phagocytosis", false]], "q": "What is the role of platelets in the body?", "wrong_explanations": {"1": "Oxygen transport = RED BLOOD CELLS using haemoglobin.", "2": "Producing antibodies = LYMPHOCYTES (a type of white blood cell).", "3": "Engulfing bacteria = PHAGOCYTES (a type of white blood cell)."}}, {"opts": [["Oxygen \u2014 this is carried by haemoglobin inside red blood cells", true], ["Glucose from the small intestine to body cells", false], ["Urea from the liver to the kidneys", false], ["Carbon dioxide from respiring cells to the lungs", false]], "q": "Which substance does plasma NOT transport?", "wrong_explanations": {"1": "Glucose IS carried in plasma \u2014 after absorption from the small intestine.", "2": "Urea IS carried in plasma \u2014 from the liver to the kidneys for excretion.", "3": "Carbon dioxide IS dissolved in plasma \u2014 most CO\u2082 travels as bicarbonate ions dissolved in plasma."}}], "TH": [{"opts": [["To create more space for haemoglobin \u2014 allowing the cell to carry more oxygen", true], ["So they can divide and replace themselves when worn out", false], ["To reduce their weight so they flow faster through blood vessels", false], ["So they can squeeze through capillaries more easily", false]], "q": "Why do red blood cells have no nucleus?", "wrong_explanations": {"1": "Cells without a nucleus CANNOT divide \u2014 red blood cells are produced in bone marrow and cannot reproduce themselves.", "2": "Weight difference between a nucleus and haemoglobin molecules is negligible \u2014 the primary reason is space for haemoglobin.", "3": "Flexibility helps red blood cells squeeze through capillaries \u2014 but this is a result of their biconcave shape and flexibility, not the absence of a nucleus."}}, {"opts": [["Unable to produce specific antibodies \u2014 prolonged or repeated infections that are hard to clear", true], ["Unable to carry oxygen \u2014 severe anaemia", false], ["Blood will not clot properly \u2014 excessive bleeding from wounds", false], ["Unable to digest food properly \u2014 nutrients not absorbed", false]], "q": "A patient has very few lymphocytes. What is the most likely consequence?", "wrong_explanations": {"1": "Oxygen carrying = RED BLOOD CELLS using haemoglobin. Lymphocytes are white blood cells.", "2": "Blood clotting = PLATELETS forming a fibrin mesh. Lymphocytes produce antibodies, not clotting factors.", "3": "Food digestion = digestive enzymes in the gut. Lymphocytes are part of the immune system."}}, {"opts": [["Blood clotting \u2014 they clump at wound sites and trigger fibrin mesh formation to seal the damage", true], ["Carrying oxygen from the lungs to body tissues", false], ["Producing antibodies to fight specific pathogens", false], ["Engulfing and digesting bacteria by phagocytosis", false]], "q": "What is the role of platelets in the body?", "wrong_explanations": {"1": "Oxygen transport = RED BLOOD CELLS using haemoglobin.", "2": "Producing antibodies = LYMPHOCYTES (a type of white blood cell).", "3": "Engulfing bacteria = PHAGOCYTES (a type of white blood cell)."}}, {"opts": [["Oxygen \u2014 this is carried by haemoglobin inside red blood cells", true], ["Glucose from the small intestine to body cells", false], ["Urea from the liver to the kidneys", false], ["Carbon dioxide from respiring cells to the lungs", false]], "q": "Which substance does plasma NOT transport?", "wrong_explanations": {"1": "Glucose IS carried in plasma \u2014 after absorption from the small intestine.", "2": "Urea IS carried in plasma \u2014 from the liver to the kidneys for excretion.", "3": "Carbon dioxide IS dissolved in plasma \u2014 most CO\u2082 travels as bicarbonate ions dissolved in plasma."}}]}, "summary": "Describe the four components of blood and the function of each.", "theory": [{"content": "Blood is a connective tissue \u2014 a liquid tissue that flows through blood vessels.\n\nIt has four main components:\n1. Red blood cells (erythrocytes)\n2. White blood cells (leucocytes)\n3. Platelets\n4. Plasma\n\nEach component has a distinct and essential function. Together they transport substances, defend against disease and maintain the body's internal environment.", "heading": "Blood \u2014 A Tissue"}, {"content": "Red blood cells carry OXYGEN from the lungs to all body tissues.\n\nThey are uniquely adapted for this function:\nBICONCAVE DISC SHAPE \u2014 increases surface area for oxygen absorption and releases carbon dioxide. The thin centre reduces the diffusion distance for gas exchange.\nNO NUCLEUS \u2014 the nucleus is lost as red blood cells mature. This creates more space for HAEMOGLOBIN \u2014 the protein that binds and carries oxygen.\nPacked with HAEMOGLOBIN \u2014 each red blood cell contains ~270 million haemoglobin molecules.\nFLEXIBLE \u2014 can squeeze through narrow capillaries without tearing.\n\nIn the lungs, haemoglobin binds to oxygen (forming oxyhaemoglobin) where oxygen concentration is high.\nIn body tissues, oxyhaemoglobin releases oxygen where concentration is low.\n\nRed blood cells are made in the bone marrow and last about 120 days before being broken down in the spleen.", "heading": "Red Blood Cells"}, {"content": "White blood cells are part of the IMMUNE SYSTEM \u2014 they defend the body against pathogens.\n\nUnlike red blood cells, white blood cells have a nucleus.\n\nThere are two main types:\n\nPHAGOCYTES:\nEngulf and destroy pathogens by PHAGOCYTOSIS \u2014 the cell membrane wraps around the pathogen and pulls it inside where enzymes digest it.\nNon-specific \u2014 they attack any pathogen they encounter.\nRespond quickly \u2014 first responders at an infection site.\n\nLYMPHOCYTES:\nProduce ANTIBODIES \u2014 proteins with a specific shape that binds to ANTIGENS on the surface of a specific pathogen.\nOne lymphocyte produces ONE type of antibody for ONE specific antigen.\nAntigens are molecules on the surface of pathogens that the immune system recognises as foreign.\nAfter infection, MEMORY LYMPHOCYTES remain in the blood for years or for life \u2014 if the same pathogen invades again, a rapid, large-scale antibody response destroys it before it can cause disease. This is the basis of IMMUNITY.", "heading": "White Blood Cells"}, {"content": "Platelets are tiny cell FRAGMENTS \u2014 they are not complete cells and have no nucleus.\n\nWhen a blood vessel is damaged, platelets are involved in BLOOD CLOTTING:\n1. Platelets are activated and clump together at the wound site.\n2. A series of chemical reactions produces FIBRIN \u2014 a protein that forms a mesh of fibres.\n3. Red blood cells are trapped in the fibrin mesh \u2192 a CLOT forms.\n4. The clot dries to form a SCAB \u2014 sealing the wound, preventing blood loss and stopping pathogens from entering.\n\nWithout platelets, even a small cut could lead to dangerous blood loss and open infection.", "heading": "Platelets"}, {"content": "Plasma is the pale yellow LIQUID component of blood \u2014 it makes up about 55% of blood volume.\n\nPlasma transports almost everything in the blood:\nDigested food molecules \u2014 glucose and amino acids from the small intestine to cells.\nCarbon dioxide \u2014 from respiring cells to the lungs.\nUrea \u2014 from the liver (where it is made) to the kidneys (where it is excreted in urine).\nHormones \u2014 from endocrine glands to their target organs.\nAntibodies \u2014 produced by lymphocytes, carried to infection sites.\nHeat \u2014 distributes warmth from active muscles to cooler parts of the body, helping regulate body temperature.", "heading": "Plasma"}]};
window.KS4SRC["periodic-table"] = {"common_mistake": "The GROUP NUMBER tells you the number of OUTER ELECTRONS \u2014 not the total electrons or the period. The PERIOD NUMBER tells you how many shells. So an element in Period 3, Group 2 has 3 shells and 2 outer electrons \u2014 electronic configuration 2.8.2 (magnesium). Don't confuse groups and periods.", "higher": "Detailed group trends explained by electronic structure. Group 1 reactivity increases down (outer electron further from nucleus, weaker attraction, lower ionisation energy). Group 7 reactivity decreases down (outer shell further, weaker pull on incoming electron). Predict properties of unknown elements from position.", "key_note": "Periodic table arranged by atomic number. Period = row = number of shells. Group = column = number of outer electrons. Same group = same outer electrons = similar properties. Metals: left and centre. Non-metals: top right. Noble gases: Group 0 (right edge).", "matching": {"instruction": "Match each feature to its correct description.", "pairs": [["Period", "A horizontal row \u2014 each new period means another electron shell"], ["Group", "A vertical column \u2014 elements share the same number of outer electrons"], ["Group 0", "Noble gases \u2014 full outer shells, very unreactive"], ["Transition metals", "Hard, dense metals with high melting points \u2014 form coloured compounds, act as catalysts"], ["Group 1", "Alkali metals \u2014 1 outer electron, very reactive, soft, low density"]], "title": "Match the Periodic Table Feature"}, "quiz": {"CF": [{"opts": [["2.8.2 \u2014 3 shells (Period 3) and 2 outer electrons (Group 2)", true], ["3.2 \u2014 period number first, then group number", false], ["2.2 \u2014 two shells and two outer electrons", false], ["2.8.3 \u2014 Period 3 means 3 electrons in the outer shell", false]], "q": "An element is in Period 3 and Group 2. What is its electronic configuration?", "wrong_explanations": {"1": "The periodic table doesn't give configurations directly \u2014 the group number is the outer electrons, but you must fill the inner shells first.", "2": "Period 3 means 3 SHELLS, not 3 electrons in the outer shell. The shells fill as 2.8.2 \u2014 inner shells full, outer shell has 2.", "3": "Period 3 means 3 SHELLS \u2014 not 3 electrons in the outermost shell. The Group number (2) gives the outer electron count."}}, {"opts": [["They all have 7 electrons in their outer shell \u2014 they react similarly by gaining one electron to achieve a full shell", true], ["They are all gases at room temperature", false], ["They all have the same number of electrons", false], ["They are all in the same period of the periodic table", false]], "q": "Why do all Group 7 elements have similar chemical properties?", "wrong_explanations": {"1": "Fluorine is a gas but iodine is a solid at room temperature \u2014 physical state varies within Group 7.", "2": "Different Group 7 elements have different numbers of electrons (F:9, Cl:17, Br:35) \u2014 the OUTER electron count (7) is what's the same.", "3": "Elements in the same group are in DIFFERENT periods \u2014 they share the same outer electron count, not the same period."}}], "CH": [{"opts": [["2.8.2 \u2014 3 shells (Period 3) and 2 outer electrons (Group 2)", true], ["3.2 \u2014 period number first, then group number", false], ["2.2 \u2014 two shells and two outer electrons", false], ["2.8.3 \u2014 Period 3 means 3 electrons in the outer shell", false]], "q": "An element is in Period 3 and Group 2. What is its electronic configuration?", "wrong_explanations": {"1": "The periodic table doesn't give configurations directly \u2014 the group number is the outer electrons, but you must fill the inner shells first.", "2": "Period 3 means 3 SHELLS, not 3 electrons in the outer shell. The shells fill as 2.8.2 \u2014 inner shells full, outer shell has 2.", "3": "Period 3 means 3 SHELLS \u2014 not 3 electrons in the outermost shell. The Group number (2) gives the outer electron count."}}, {"opts": [["They all have 7 electrons in their outer shell \u2014 they react similarly by gaining one electron to achieve a full shell", true], ["They are all gases at room temperature", false], ["They all have the same number of electrons", false], ["They are all in the same period of the periodic table", false]], "q": "Why do all Group 7 elements have similar chemical properties?", "wrong_explanations": {"1": "Fluorine is a gas but iodine is a solid at room temperature \u2014 physical state varies within Group 7.", "2": "Different Group 7 elements have different numbers of electrons (F:9, Cl:17, Br:35) \u2014 the OUTER electron count (7) is what's the same.", "3": "Elements in the same group are in DIFFERENT periods \u2014 they share the same outer electron count, not the same period."}}], "TF": [{"opts": [["2.8.2 \u2014 3 shells (Period 3) and 2 outer electrons (Group 2)", true], ["3.2 \u2014 period number first, then group number", false], ["2.2 \u2014 two shells and two outer electrons", false], ["2.8.3 \u2014 Period 3 means 3 electrons in the outer shell", false]], "q": "An element is in Period 3 and Group 2. What is its electronic configuration?", "wrong_explanations": {"1": "The periodic table doesn't give configurations directly \u2014 the group number is the outer electrons, but you must fill the inner shells first.", "2": "Period 3 means 3 SHELLS, not 3 electrons in the outer shell. The shells fill as 2.8.2 \u2014 inner shells full, outer shell has 2.", "3": "Period 3 means 3 SHELLS \u2014 not 3 electrons in the outermost shell. The Group number (2) gives the outer electron count."}}, {"opts": [["They all have 7 electrons in their outer shell \u2014 they react similarly by gaining one electron to achieve a full shell", true], ["They are all gases at room temperature", false], ["They all have the same number of electrons", false], ["They are all in the same period of the periodic table", false]], "q": "Why do all Group 7 elements have similar chemical properties?", "wrong_explanations": {"1": "Fluorine is a gas but iodine is a solid at room temperature \u2014 physical state varies within Group 7.", "2": "Different Group 7 elements have different numbers of electrons (F:9, Cl:17, Br:35) \u2014 the OUTER electron count (7) is what's the same.", "3": "Elements in the same group are in DIFFERENT periods \u2014 they share the same outer electron count, not the same period."}}], "TH": [{"opts": [["2.8.2 \u2014 3 shells (Period 3) and 2 outer electrons (Group 2)", true], ["3.2 \u2014 period number first, then group number", false], ["2.2 \u2014 two shells and two outer electrons", false], ["2.8.3 \u2014 Period 3 means 3 electrons in the outer shell", false]], "q": "An element is in Period 3 and Group 2. What is its electronic configuration?", "wrong_explanations": {"1": "The periodic table doesn't give configurations directly \u2014 the group number is the outer electrons, but you must fill the inner shells first.", "2": "Period 3 means 3 SHELLS, not 3 electrons in the outer shell. The shells fill as 2.8.2 \u2014 inner shells full, outer shell has 2.", "3": "Period 3 means 3 SHELLS \u2014 not 3 electrons in the outermost shell. The Group number (2) gives the outer electron count."}}, {"opts": [["They all have 7 electrons in their outer shell \u2014 they react similarly by gaining one electron to achieve a full shell", true], ["They are all gases at room temperature", false], ["They all have the same number of electrons", false], ["They are all in the same period of the periodic table", false]], "q": "Why do all Group 7 elements have similar chemical properties?", "wrong_explanations": {"1": "Fluorine is a gas but iodine is a solid at room temperature \u2014 physical state varies within Group 7.", "2": "Different Group 7 elements have different numbers of electrons (F:9, Cl:17, Br:35) \u2014 the OUTER electron count (7) is what's the same.", "3": "Elements in the same group are in DIFFERENT periods \u2014 they share the same outer electron count, not the same period."}}]}, "summary": "Describe the structure of the periodic table and explain how it is organised.", "theory": [{"content": "The PERIODIC TABLE arranges all known elements in order of increasing ATOMIC NUMBER.\n\nKey features:\nROWS are called PERIODS \u2014 each period represents a new electron shell being filled.\nCOLUMNS are called GROUPS \u2014 elements in the same group have the same number of OUTER ELECTRONS and similar chemical properties.\n\nPeriod numbers tell you how many electron shells the element has:\nPeriod 1: 1 shell (H and He)\nPeriod 2: 2 shells (Li to Ne)\nPeriod 3: 3 shells (Na to Ar)\n\nGroup numbers (1\u20137 and 0) tell you how many OUTER electrons:\nGroup 1: 1 outer electron\nGroup 7: 7 outer electrons\nGroup 0: full outer shell (8 electrons, or 2 for helium)\n\nThe periodic table is divided into:\nMETALS \u2014 left and centre (most elements are metals).\nNON-METALS \u2014 top right.\nMETALLOIDS/SEMI-METALS \u2014 along the dividing line (e.g. silicon, germanium).", "heading": "Structure of the Periodic Table"}, {"content": "ACROSS A PERIOD (left to right):\nAtomic number increases.\nNumber of electrons in outer shell increases (1 to 8).\nMetallic properties decrease \u2014 non-metallic properties increase.\nFrom metal (Group 1) to non-metal (Group 7) to noble gas (Group 0).\n\nDOWN A GROUP:\nAnother electron shell is added.\nAtoms get LARGER (more shells = bigger atom).\nOUTER ELECTRONS are further from the nucleus \u2014 less strongly attracted.\nMETALS become MORE REACTIVE going down (easier to lose outer electron).\nNON-METALS become LESS REACTIVE going down (harder to gain another electron \u2014 outer electrons are further away).\n\nThese trends allow chemists to PREDICT the properties of elements from their position in the periodic table.", "heading": "Trends Across Periods and Down Groups"}, {"content": "Between Groups 2 and 3 lies the TRANSITION METALS block (the long middle section).\n\nTransition metals are harder and have higher melting points than Group 1 metals.\nThey are typically dense, strong, shiny metals.\nExamples: iron (Fe), copper (Cu), zinc (Zn), titanium (Ti), nickel (Ni), gold (Au), silver (Ag).\n\nKey properties of transition metals:\nForm COLOURED COMPOUNDS \u2014 e.g. copper sulfate is blue; iron(II) compounds are pale green; iron(III) compounds are orange.\nCan act as CATALYSTS \u2014 e.g. iron catalyst in the Haber process; nickel in hydrogenation.\nCan have MULTIPLE OXIDATION STATES \u2014 e.g. iron can be Fe\u00b2\u207a or Fe\u00b3\u207a.\n\nCompare with Group 1 metals: transition metals are less reactive, harder, have higher melting points and form coloured compounds. Group 1 metals are soft, very reactive and their compounds are usually white.", "heading": "Transition Metals"}]};
window.KS4SRC["thermal-conductivity"] = {"common_mistake": "INSULATORS do not stop heat transfer \u2014 they slow it down. A perfect insulator doesn't exist. Trapped air is one of the best insulators because air is a poor conductor and convection is reduced when it is trapped in small spaces.", "higher": "Describe the factors affecting the rate of thermal conduction: thermal conductivity, thickness and temperature difference. Calculate rate of energy transfer through a material. Evaluate different insulation methods quantitatively using U-values or thermal conductivity data. Explain why double-glazing is more effective with wider gaps.", "key_note": "Thermal conductivity: rate of energy transfer by conduction. Metals = good conductors (free electrons). Air/fibreglass = good insulators. Reducing losses: insulation, lubrication, streamlining. Thicker insulation = less energy lost. RP2: compare materials by rate of cooling.", "matching": {"instruction": "Match each material to its thermal conductivity property.", "pairs": [["Copper", "Very high thermal conductivity \u2014 free electrons transfer energy rapidly"], ["Air (trapped)", "Very low thermal conductivity \u2014 excellent insulator when trapped"], ["Cavity wall insulation", "Fibreglass with trapped air \u2014 reduces energy loss through walls"], ["Lubrication", "Reduces friction between surfaces \u2014 less energy wasted as heat"]], "title": "Thermal Conductivity"}, "quiz": {"CF": [{"opts": [["Air has much lower thermal conductivity than glass \u2014 it transfers energy by conduction very slowly", true], ["Air is lighter than glass \u2014 lower density means less thermal energy stored", false], ["Glass transmits light which carries thermal energy \u2014 air does not", false], ["Air molecules move randomly, transferring energy away from hot objects faster", false]], "q": "Why is trapped air a better insulator than glass?", "wrong_explanations": {"1": "Density affects heat capacity but not thermal conductivity directly \u2014 air's insulating property comes from its very low thermal conductivity.", "2": "Light transmission (transparency) is unrelated to thermal conductivity.", "3": "Moving air molecules would increase CONVECTION \u2014 trapped air cannot convect, so only slow conduction occurs."}}, {"opts": [["Rate of temperature decrease \u2014 steeper temperature-time graph = less effective insulator", true], ["Final temperature after 10 minutes \u2014 higher temperature = better conductor", false], ["Mass of insulating material used \u2014 more mass = more insulation", false], ["Colour of the insulating material \u2014 darker colours absorb more radiation", false]], "q": "A student investigates thermal insulators by wrapping identical beakers in different materials. Which measurement gives the best comparison?", "wrong_explanations": {"1": "Final temperature alone doesn't account for starting conditions or time \u2014 rate of cooling (gradient) is a fairer comparison.", "2": "Mass is not controlled in this way \u2014 thickness and type of material matter, not total mass.", "3": "Colour affects radiation absorption \u2014 relevant for infrared studies but not primary factor in conduction-based insulation tests."}}], "CH": [{"opts": [["Air has much lower thermal conductivity than glass \u2014 it transfers energy by conduction very slowly", true], ["Air is lighter than glass \u2014 lower density means less thermal energy stored", false], ["Glass transmits light which carries thermal energy \u2014 air does not", false], ["Air molecules move randomly, transferring energy away from hot objects faster", false]], "q": "Why is trapped air a better insulator than glass?", "wrong_explanations": {"1": "Density affects heat capacity but not thermal conductivity directly \u2014 air's insulating property comes from its very low thermal conductivity.", "2": "Light transmission (transparency) is unrelated to thermal conductivity.", "3": "Moving air molecules would increase CONVECTION \u2014 trapped air cannot convect, so only slow conduction occurs."}}, {"opts": [["Rate of temperature decrease \u2014 steeper temperature-time graph = less effective insulator", true], ["Final temperature after 10 minutes \u2014 higher temperature = better conductor", false], ["Mass of insulating material used \u2014 more mass = more insulation", false], ["Colour of the insulating material \u2014 darker colours absorb more radiation", false]], "q": "A student investigates thermal insulators by wrapping identical beakers in different materials. Which measurement gives the best comparison?", "wrong_explanations": {"1": "Final temperature alone doesn't account for starting conditions or time \u2014 rate of cooling (gradient) is a fairer comparison.", "2": "Mass is not controlled in this way \u2014 thickness and type of material matter, not total mass.", "3": "Colour affects radiation absorption \u2014 relevant for infrared studies but not primary factor in conduction-based insulation tests."}}], "TF": [{"opts": [["Air has much lower thermal conductivity than glass \u2014 it transfers energy by conduction very slowly", true], ["Air is lighter than glass \u2014 lower density means less thermal energy stored", false], ["Glass transmits light which carries thermal energy \u2014 air does not", false], ["Air molecules move randomly, transferring energy away from hot objects faster", false]], "q": "Why is trapped air a better insulator than glass?", "wrong_explanations": {"1": "Density affects heat capacity but not thermal conductivity directly \u2014 air's insulating property comes from its very low thermal conductivity.", "2": "Light transmission (transparency) is unrelated to thermal conductivity.", "3": "Moving air molecules would increase CONVECTION \u2014 trapped air cannot convect, so only slow conduction occurs."}}, {"opts": [["Rate of temperature decrease \u2014 steeper temperature-time graph = less effective insulator", true], ["Final temperature after 10 minutes \u2014 higher temperature = better conductor", false], ["Mass of insulating material used \u2014 more mass = more insulation", false], ["Colour of the insulating material \u2014 darker colours absorb more radiation", false]], "q": "A student investigates thermal insulators by wrapping identical beakers in different materials. Which measurement gives the best comparison?", "wrong_explanations": {"1": "Final temperature alone doesn't account for starting conditions or time \u2014 rate of cooling (gradient) is a fairer comparison.", "2": "Mass is not controlled in this way \u2014 thickness and type of material matter, not total mass.", "3": "Colour affects radiation absorption \u2014 relevant for infrared studies but not primary factor in conduction-based insulation tests."}}], "TH": [{"opts": [["Air has much lower thermal conductivity than glass \u2014 it transfers energy by conduction very slowly", true], ["Air is lighter than glass \u2014 lower density means less thermal energy stored", false], ["Glass transmits light which carries thermal energy \u2014 air does not", false], ["Air molecules move randomly, transferring energy away from hot objects faster", false]], "q": "Why is trapped air a better insulator than glass?", "wrong_explanations": {"1": "Density affects heat capacity but not thermal conductivity directly \u2014 air's insulating property comes from its very low thermal conductivity.", "2": "Light transmission (transparency) is unrelated to thermal conductivity.", "3": "Moving air molecules would increase CONVECTION \u2014 trapped air cannot convect, so only slow conduction occurs."}}, {"opts": [["Rate of temperature decrease \u2014 steeper temperature-time graph = less effective insulator", true], ["Final temperature after 10 minutes \u2014 higher temperature = better conductor", false], ["Mass of insulating material used \u2014 more mass = more insulation", false], ["Colour of the insulating material \u2014 darker colours absorb more radiation", false]], "q": "A student investigates thermal insulators by wrapping identical beakers in different materials. Which measurement gives the best comparison?", "wrong_explanations": {"1": "Final temperature alone doesn't account for starting conditions or time \u2014 rate of cooling (gradient) is a fairer comparison.", "2": "Mass is not controlled in this way \u2014 thickness and type of material matter, not total mass.", "3": "Colour affects radiation absorption \u2014 relevant for infrared studies but not primary factor in conduction-based insulation tests."}}]}, "rp": "RP2 (physics only) \u2014 Investigate effectiveness of different thermal insulators. Measure rate of cooling of hot water wrapped in different materials.", "summary": "Explain thermal conductivity and describe how insulation reduces unwanted energy transfers.", "theory": [{"content": "THERMAL CONDUCTIVITY measures how well a material transfers thermal energy by conduction.\n\nGood THERMAL CONDUCTORS: metals (copper, aluminium, iron). Transfer energy quickly. Free electrons carry thermal energy through the material.\n\nGood THERMAL INSULATORS: air, wood, fibreglass, polystyrene, wool. Transfer energy slowly. No free electrons; energy transferred only by vibration between tightly packed or sparse particles.\n\nUnit of thermal conductivity: W/m\u00b7K (watts per metre per kelvin).\n\nHigher thermal conductivity \u2192 energy transferred faster for the same temperature difference and thickness.\n\nExamples:\nCopper: ~400 W/m\u00b7K \u2014 excellent conductor.\nGlass: ~1 W/m\u00b7K \u2014 poor conductor.\nAir: ~0.025 W/m\u00b7K \u2014 excellent insulator.", "heading": "Thermal Conductivity"}, {"content": "All energy transfers involve some unwanted dissipation \u2014 energy transferred to the thermal store of the surroundings.\n\nMETHODS TO REDUCE THERMAL ENERGY LOSS:\n\n1. INSULATION:\nSurround objects with poor conductors.\nCavity wall insulation (fibreglass or foam) \u2014 reduces conduction through walls.\nLoft insulation \u2014 reduces conduction through roof.\nDouble-glazing \u2014 air gap between panes of glass reduces conduction.\nFoam lagging on hot water pipes \u2014 reduces heat loss to surroundings.\n\n2. LUBRICATION:\nReduces friction between moving surfaces.\nLess friction \u2192 less thermal energy dissipated.\nMachine oil, grease used in engines, bearings, chains.\n\n3. STREAMLINING:\nReduces air resistance on moving vehicles.\nLess drag \u2192 less energy wasted overcoming resistance.\n\n4. ELECTROMAGNETIC SHIELDING:\nReduces energy loss from electrical components.\n\nTHICKNESS AND THERMAL CONDUCTIVITY:\nThicker insulation \u2192 less energy transferred per second (for same temperature difference).\nMore insulating material (lower conductivity) \u2192 less energy transferred.\nEnergy lost per second \u221d thermal conductivity \u00d7 area \u00d7 (temperature difference) \u00f7 thickness.", "heading": "Reducing Unwanted Energy Transfers"}, {"content": "REQUIRED PRACTICAL (RP2 \u2014 physics only):\nInvestigate the effectiveness of different materials as thermal insulators.\n\nMETHOD:\nWrap beakers of hot water in different materials (wool, bubble wrap, newspaper, foil).\nMeasure temperature of water at regular time intervals.\nPlot temperature-time graphs for each material.\nCompare rate of cooling \u2014 steeper gradient = less effective insulator.\n\nVARIABLES:\nIndependent: type of insulating material.\nDependent: rate of cooling (temperature change per unit time).\nControlled: initial temperature, volume of water, thickness of insulation, surface area.\n\nCONCLUSION:\nMaterial with lowest thermal conductivity \u2192 slowest cooling \u2192 best insulator.\nAir is often the best insulator \u2014 sealed air pockets in fibreglass work well.\n\nAPPLICATIONS:\nBuilding insulation \u2014 reduces heating bills and carbon footprint.\nRefrigeration \u2014 insulated walls slow thermal energy entering the cold space.\nCryogenics \u2014 extreme insulation to maintain very low temperatures.", "heading": "Required Practical \u2014 Thermal Insulation"}]};
window.KS4SRC["coronary-heart-disease"] = {"common_mistake": "A STENT holds a narrowed artery open \u2014 it does NOT bypass the blockage. A BYPASS SURGERY creates a new route around the blockage using a grafted blood vessel. Students often confuse these two treatments.", "higher": "Statins lower LDL cholesterol \u2014 slowing fatty deposit formation in arteries. Stents keep coronary arteries open mechanically. Bypass surgery grafts a vessel (usually from the leg) around the blockage. Heart transplants replace the whole heart \u2014 require immunosuppression. Artificial hearts provide temporary support. Faulty valves can be replaced with biological or mechanical alternatives. Each treatment has risks (surgery complications, rejection, infection) and benefits to evaluate.", "key_note": "CHD = narrowed coronary arteries (atherosclerosis/plaques). Risk factors: smoking, high cholesterol, high blood pressure, poor diet, lack of exercise. Treatments: statins (lower cholesterol), stents (hold artery open), bypass surgery (reroute blood).", "matching": {"instruction": "Match each treatment to its mechanism.", "pairs": [["Statins", "Drugs that lower LDL cholesterol in the blood \u2014 slow plaque formation"], ["Stent", "Metal mesh tube inserted into a narrowed artery to hold it open"], ["Bypass surgery", "Grafts a healthy blood vessel around the blocked coronary artery"], ["Heart transplant", "Replaces the diseased heart \u2014 last resort, risk of rejection"]], "title": "Match the CHD Treatment to How it Works"}, "quiz": {"CF": [{"opts": [["Fatty plaques (atherosclerosis) build up in the coronary arteries, narrowing them and reducing blood flow to the heart muscle", true], ["The heart muscle becomes too weak to pump blood effectively due to overuse", false], ["Blood becomes too thick and cannot flow through the coronary arteries", false], ["The coronary arteries grow too narrow naturally with age", false]], "q": "What causes coronary heart disease?", "wrong_explanations": {"1": "Heart muscle weakness (heart failure) is a consequence of CHD, not the cause \u2014 the cause is specifically fatty plaque build-up.", "2": "Blood viscosity can affect flow, but CHD is specifically about PLAQUE build-up in artery walls, not blood thickness.", "3": "Arteries don't naturally narrow with age \u2014 they narrow because of PLAQUES (fatty deposits) accumulating over time due to risk factors."}}, {"opts": [["It is inserted into the narrowed artery and expands to hold it open \u2014 restoring blood flow", true], ["It dissolves the fatty plaques blocking the artery", false], ["It reroutes blood around the blocked artery using a grafted vessel", false], ["It lowers blood cholesterol levels to prevent further plaque formation", false]], "q": "How does a stent treat coronary heart disease?", "wrong_explanations": {"1": "Stents do not dissolve plaques \u2014 they physically hold the narrowed artery open.", "2": "Rerouting blood around a blockage using a grafted vessel = BYPASS SURGERY, not a stent.", "3": "Lowering cholesterol = STATINS (medication), not a stent."}}, {"opts": [["Smoking cigarettes", true], ["Family history of heart disease (genetics)", false], ["Being male", false], ["Increasing age", false]], "q": "Which of the following is a lifestyle risk factor for CHD that CAN be changed?", "wrong_explanations": {"1": "Genetics is a risk factor \u2014 but you cannot change your DNA. It is a non-modifiable risk factor.", "2": "Sex (being male) slightly increases CHD risk, particularly at younger ages \u2014 but you cannot change this.", "3": "Age increases CHD risk, but everyone ages \u2014 you cannot avoid this risk factor."}}], "CH": [{"opts": [["Fatty plaques (atherosclerosis) build up in the coronary arteries, narrowing them and reducing blood flow to the heart muscle", true], ["The heart muscle becomes too weak to pump blood effectively due to overuse", false], ["Blood becomes too thick and cannot flow through the coronary arteries", false], ["The coronary arteries grow too narrow naturally with age", false]], "q": "What causes coronary heart disease?", "wrong_explanations": {"1": "Heart muscle weakness (heart failure) is a consequence of CHD, not the cause \u2014 the cause is specifically fatty plaque build-up.", "2": "Blood viscosity can affect flow, but CHD is specifically about PLAQUE build-up in artery walls, not blood thickness.", "3": "Arteries don't naturally narrow with age \u2014 they narrow because of PLAQUES (fatty deposits) accumulating over time due to risk factors."}}, {"opts": [["It is inserted into the narrowed artery and expands to hold it open \u2014 restoring blood flow", true], ["It dissolves the fatty plaques blocking the artery", false], ["It reroutes blood around the blocked artery using a grafted vessel", false], ["It lowers blood cholesterol levels to prevent further plaque formation", false]], "q": "How does a stent treat coronary heart disease?", "wrong_explanations": {"1": "Stents do not dissolve plaques \u2014 they physically hold the narrowed artery open.", "2": "Rerouting blood around a blockage using a grafted vessel = BYPASS SURGERY, not a stent.", "3": "Lowering cholesterol = STATINS (medication), not a stent."}}, {"opts": [["Smoking cigarettes", true], ["Family history of heart disease (genetics)", false], ["Being male", false], ["Increasing age", false]], "q": "Which of the following is a lifestyle risk factor for CHD that CAN be changed?", "wrong_explanations": {"1": "Genetics is a risk factor \u2014 but you cannot change your DNA. It is a non-modifiable risk factor.", "2": "Sex (being male) slightly increases CHD risk, particularly at younger ages \u2014 but you cannot change this.", "3": "Age increases CHD risk, but everyone ages \u2014 you cannot avoid this risk factor."}}], "TF": [{"opts": [["Fatty plaques (atherosclerosis) build up in the coronary arteries, narrowing them and reducing blood flow to the heart muscle", true], ["The heart muscle becomes too weak to pump blood effectively due to overuse", false], ["Blood becomes too thick and cannot flow through the coronary arteries", false], ["The coronary arteries grow too narrow naturally with age", false]], "q": "What causes coronary heart disease?", "wrong_explanations": {"1": "Heart muscle weakness (heart failure) is a consequence of CHD, not the cause \u2014 the cause is specifically fatty plaque build-up.", "2": "Blood viscosity can affect flow, but CHD is specifically about PLAQUE build-up in artery walls, not blood thickness.", "3": "Arteries don't naturally narrow with age \u2014 they narrow because of PLAQUES (fatty deposits) accumulating over time due to risk factors."}}, {"opts": [["It is inserted into the narrowed artery and expands to hold it open \u2014 restoring blood flow", true], ["It dissolves the fatty plaques blocking the artery", false], ["It reroutes blood around the blocked artery using a grafted vessel", false], ["It lowers blood cholesterol levels to prevent further plaque formation", false]], "q": "How does a stent treat coronary heart disease?", "wrong_explanations": {"1": "Stents do not dissolve plaques \u2014 they physically hold the narrowed artery open.", "2": "Rerouting blood around a blockage using a grafted vessel = BYPASS SURGERY, not a stent.", "3": "Lowering cholesterol = STATINS (medication), not a stent."}}, {"opts": [["Smoking cigarettes", true], ["Family history of heart disease (genetics)", false], ["Being male", false], ["Increasing age", false]], "q": "Which of the following is a lifestyle risk factor for CHD that CAN be changed?", "wrong_explanations": {"1": "Genetics is a risk factor \u2014 but you cannot change your DNA. It is a non-modifiable risk factor.", "2": "Sex (being male) slightly increases CHD risk, particularly at younger ages \u2014 but you cannot change this.", "3": "Age increases CHD risk, but everyone ages \u2014 you cannot avoid this risk factor."}}], "TH": [{"opts": [["Fatty plaques (atherosclerosis) build up in the coronary arteries, narrowing them and reducing blood flow to the heart muscle", true], ["The heart muscle becomes too weak to pump blood effectively due to overuse", false], ["Blood becomes too thick and cannot flow through the coronary arteries", false], ["The coronary arteries grow too narrow naturally with age", false]], "q": "What causes coronary heart disease?", "wrong_explanations": {"1": "Heart muscle weakness (heart failure) is a consequence of CHD, not the cause \u2014 the cause is specifically fatty plaque build-up.", "2": "Blood viscosity can affect flow, but CHD is specifically about PLAQUE build-up in artery walls, not blood thickness.", "3": "Arteries don't naturally narrow with age \u2014 they narrow because of PLAQUES (fatty deposits) accumulating over time due to risk factors."}}, {"opts": [["It is inserted into the narrowed artery and expands to hold it open \u2014 restoring blood flow", true], ["It dissolves the fatty plaques blocking the artery", false], ["It reroutes blood around the blocked artery using a grafted vessel", false], ["It lowers blood cholesterol levels to prevent further plaque formation", false]], "q": "How does a stent treat coronary heart disease?", "wrong_explanations": {"1": "Stents do not dissolve plaques \u2014 they physically hold the narrowed artery open.", "2": "Rerouting blood around a blockage using a grafted vessel = BYPASS SURGERY, not a stent.", "3": "Lowering cholesterol = STATINS (medication), not a stent."}}, {"opts": [["Smoking cigarettes", true], ["Family history of heart disease (genetics)", false], ["Being male", false], ["Increasing age", false]], "q": "Which of the following is a lifestyle risk factor for CHD that CAN be changed?", "wrong_explanations": {"1": "Genetics is a risk factor \u2014 but you cannot change your DNA. It is a non-modifiable risk factor.", "2": "Sex (being male) slightly increases CHD risk, particularly at younger ages \u2014 but you cannot change this.", "3": "Age increases CHD risk, but everyone ages \u2014 you cannot avoid this risk factor."}}]}, "summary": "Describe the causes and treatments of coronary heart disease.", "theory": [{"content": "Coronary heart disease (CHD) is a condition in which the CORONARY ARTERIES \u2014 the blood vessels that supply the heart muscle itself with oxygen and glucose \u2014 become narrowed and partially or completely blocked.\n\nThe heart muscle is always active, always respiring \u2014 it needs a continuous supply of oxygen. If this supply is reduced or cut off, the heart muscle cannot function properly.\n\nCHD is one of the leading causes of death in the UK and worldwide.", "heading": "What is Coronary Heart Disease?"}, {"content": "CHD develops through a process called ATHEROSCLEROSIS:\n\n1. Over many years, fatty substances (mainly cholesterol) build up in the walls of the coronary arteries.\n2. These fatty deposits are called PLAQUES or ATHEROMAS.\n3. The plaques harden over time, making artery walls less elastic.\n4. The lumen (central channel) of the artery becomes progressively NARROWER.\n5. Blood flow to the heart muscle is reduced.\n6. If a plaque ruptures, a BLOOD CLOT can form at that site \u2014 this can completely block the artery.\n\nComplete blockage = HEART ATTACK. The heart muscle supplied by that artery receives no oxygen and begins to die. This causes severe chest pain, shortness of breath and can be fatal.", "heading": "How CHD Develops \u2014 Atherosclerosis"}, {"content": "Several factors increase the risk of developing CHD:\n\nLIFESTYLE FACTORS (can be changed):\nSMOKING \u2014 carbon monoxide damages artery walls; nicotine increases heart rate and blood pressure.\nHIGH BLOOD CHOLESTEROL \u2014 excess cholesterol deposits in artery walls forming plaques.\nHIGH BLOOD PRESSURE \u2014 damages artery walls, making them more susceptible to plaque formation.\nPOOR DIET \u2014 high in saturated fats and salt raises cholesterol and blood pressure.\nLACK OF EXERCISE \u2014 physical activity strengthens the heart and helps control weight and cholesterol.\nOBESITY \u2014 associated with high blood pressure, high cholesterol and type 2 diabetes.\n\nNON-LIFESTYLE FACTORS (cannot be changed):\nGENETICS \u2014 family history of CHD significantly increases risk.\nAGE \u2014 risk increases with age as arteries gradually narrow.\nSEX \u2014 males tend to develop CHD at younger ages than females (though risk equalises after menopause).", "heading": "Risk Factors for CHD"}, {"content": "Several treatments can reduce the effects of CHD:\n\nSTATINS (medication):\nDrugs that reduce the level of LDL cholesterol in the blood.\nSlows the build-up of plaques in arteries.\nTaken daily \u2014 can significantly reduce heart attack and stroke risk.\nSide effects: muscle pain in some patients.\n\nSTENTS (surgical):\nA small metal mesh tube inserted into a narrowed coronary artery.\nHolds the artery open, restoring blood flow.\nInserted during a procedure called angioplasty \u2014 a thin tube is passed through a blood vessel to the narrowed area.\nEffective but does not treat the underlying cause.\n\nBYPASS SURGERY:\nA healthy blood vessel from another part of the body (e.g. leg vein) is grafted around the blocked section of coronary artery.\nCreates a new route for blood to reach the heart muscle.\nMajor surgery with risks, but effective for severe blockages.\n\nHEART TRANSPLANT:\nReplacing the entire diseased heart with a donor heart.\nLast resort for severe heart failure.\nRisks: immune rejection, waiting time for a suitable donor.\nPatient must take immunosuppressant drugs for life to prevent rejection.", "heading": "Treatments for CHD"}]};
window.KS4SRC["biodiversity"] = {"common_mistake": "Biodiversity is NOT just about the NUMBER of species \u2014 it also includes the RELATIVE ABUNDANCE of each species. An ecosystem with 100 species but 99% of the biomass belonging to just one species has LOW biodiversity in practice. High biodiversity means many species AND reasonable numbers of each.", "higher": "The impact of environmental change on biodiversity: habitat destruction, climate change, invasive species, pollution and overexploitation all reduce biodiversity. Students should be able to evaluate conservation strategies \u2014 protected areas, captive breeding, seed banks, habitat restoration \u2014 considering their effectiveness, cost and limitations. International agreements (e.g. Convention on Biological Diversity) coordinate global conservation efforts.", "key_note": "Biodiversity = species diversity + genetic diversity. Importance: ecosystem services (food, medicine, clean water, pollination), stability, ethical reasons. Threats: habitat loss, pollution, invasive species, overexploitation, climate change. Conservation: protected areas, captive breeding, seed banks, legislation.", "matching": {"instruction": "Sort each example into a threat to biodiversity or a conservation measure.", "pairs": [["Threat", "Deforestation \u2014 habitat destroyed for agriculture or timber"], ["Conservation", "Captive breeding programmes \u2014 endangered species bred in zoos to prevent extinction"], ["Threat", "Invasive species \u2014 grey squirrels outcompeting native red squirrels"], ["Conservation", "Seed banks \u2014 storing seeds of thousands of plant varieties as genetic insurance"], ["Threat", "Overfishing \u2014 fish populations reduced below sustainable levels"], ["Conservation", "Marine protected areas \u2014 fishing banned to allow fish stocks to recover"]], "title": "Threat or Conservation Measure?"}, "quiz": {"CF": [{"opts": [["A genetically diverse population is more adaptable \u2014 some individuals will have alleles giving resistance to new diseases or tolerance of changing conditions", true], ["Genetic diversity makes individuals physically larger and stronger", false], ["Genetic diversity allows a species to reproduce more rapidly", false], ["Genetic diversity means all individuals look different \u2014 making them harder for predators to target", false]], "q": "Why is high genetic diversity within a species important?", "wrong_explanations": {"1": "Genetic diversity doesn't directly affect physical size \u2014 size is just one trait among many.", "2": "Reproductive rate is not directly linked to genetic diversity \u2014 it depends on life history traits specific to the species.", "3": "Variation in appearance can help avoid predators \u2014 but the primary ecological importance of genetic diversity is ADAPTABILITY to change."}}, {"opts": [["They store seeds of thousands of plant varieties \u2014 preserving genetic diversity as insurance against extinction of wild populations", true], ["They grow plants for replanting in habitats where species have become locally extinct", false], ["They store seeds of food crops only \u2014 to ensure human food security", false], ["They sell seeds to farmers to encourage growing a wider variety of crops", false]], "q": "Why are seed banks important for biodiversity conservation?", "wrong_explanations": {"1": "Seed banks primarily STORE seeds in long-term preservation conditions \u2014 they are not generally growing facilities or nurseries (though some seed banks do have growing programmes).", "2": "Seed banks like the Svalbard Global Seed Vault store seeds of wild plant species AND crop varieties \u2014 not food crops only.", "3": "Seed banks are conservation facilities \u2014 not commercial enterprises, though some seed collections are used to support farmers."}}], "CH": [{"opts": [["A genetically diverse population is more adaptable \u2014 some individuals will have alleles giving resistance to new diseases or tolerance of changing conditions", true], ["Genetic diversity makes individuals physically larger and stronger", false], ["Genetic diversity allows a species to reproduce more rapidly", false], ["Genetic diversity means all individuals look different \u2014 making them harder for predators to target", false]], "q": "Why is high genetic diversity within a species important?", "wrong_explanations": {"1": "Genetic diversity doesn't directly affect physical size \u2014 size is just one trait among many.", "2": "Reproductive rate is not directly linked to genetic diversity \u2014 it depends on life history traits specific to the species.", "3": "Variation in appearance can help avoid predators \u2014 but the primary ecological importance of genetic diversity is ADAPTABILITY to change."}}, {"opts": [["They store seeds of thousands of plant varieties \u2014 preserving genetic diversity as insurance against extinction of wild populations", true], ["They grow plants for replanting in habitats where species have become locally extinct", false], ["They store seeds of food crops only \u2014 to ensure human food security", false], ["They sell seeds to farmers to encourage growing a wider variety of crops", false]], "q": "Why are seed banks important for biodiversity conservation?", "wrong_explanations": {"1": "Seed banks primarily STORE seeds in long-term preservation conditions \u2014 they are not generally growing facilities or nurseries (though some seed banks do have growing programmes).", "2": "Seed banks like the Svalbard Global Seed Vault store seeds of wild plant species AND crop varieties \u2014 not food crops only.", "3": "Seed banks are conservation facilities \u2014 not commercial enterprises, though some seed collections are used to support farmers."}}], "TF": [{"opts": [["A genetically diverse population is more adaptable \u2014 some individuals will have alleles giving resistance to new diseases or tolerance of changing conditions", true], ["Genetic diversity makes individuals physically larger and stronger", false], ["Genetic diversity allows a species to reproduce more rapidly", false], ["Genetic diversity means all individuals look different \u2014 making them harder for predators to target", false]], "q": "Why is high genetic diversity within a species important?", "wrong_explanations": {"1": "Genetic diversity doesn't directly affect physical size \u2014 size is just one trait among many.", "2": "Reproductive rate is not directly linked to genetic diversity \u2014 it depends on life history traits specific to the species.", "3": "Variation in appearance can help avoid predators \u2014 but the primary ecological importance of genetic diversity is ADAPTABILITY to change."}}, {"opts": [["They store seeds of thousands of plant varieties \u2014 preserving genetic diversity as insurance against extinction of wild populations", true], ["They grow plants for replanting in habitats where species have become locally extinct", false], ["They store seeds of food crops only \u2014 to ensure human food security", false], ["They sell seeds to farmers to encourage growing a wider variety of crops", false]], "q": "Why are seed banks important for biodiversity conservation?", "wrong_explanations": {"1": "Seed banks primarily STORE seeds in long-term preservation conditions \u2014 they are not generally growing facilities or nurseries (though some seed banks do have growing programmes).", "2": "Seed banks like the Svalbard Global Seed Vault store seeds of wild plant species AND crop varieties \u2014 not food crops only.", "3": "Seed banks are conservation facilities \u2014 not commercial enterprises, though some seed collections are used to support farmers."}}], "TH": [{"opts": [["A genetically diverse population is more adaptable \u2014 some individuals will have alleles giving resistance to new diseases or tolerance of changing conditions", true], ["Genetic diversity makes individuals physically larger and stronger", false], ["Genetic diversity allows a species to reproduce more rapidly", false], ["Genetic diversity means all individuals look different \u2014 making them harder for predators to target", false]], "q": "Why is high genetic diversity within a species important?", "wrong_explanations": {"1": "Genetic diversity doesn't directly affect physical size \u2014 size is just one trait among many.", "2": "Reproductive rate is not directly linked to genetic diversity \u2014 it depends on life history traits specific to the species.", "3": "Variation in appearance can help avoid predators \u2014 but the primary ecological importance of genetic diversity is ADAPTABILITY to change."}}, {"opts": [["They store seeds of thousands of plant varieties \u2014 preserving genetic diversity as insurance against extinction of wild populations", true], ["They grow plants for replanting in habitats where species have become locally extinct", false], ["They store seeds of food crops only \u2014 to ensure human food security", false], ["They sell seeds to farmers to encourage growing a wider variety of crops", false]], "q": "Why are seed banks important for biodiversity conservation?", "wrong_explanations": {"1": "Seed banks primarily STORE seeds in long-term preservation conditions \u2014 they are not generally growing facilities or nurseries (though some seed banks do have growing programmes).", "2": "Seed banks like the Svalbard Global Seed Vault store seeds of wild plant species AND crop varieties \u2014 not food crops only.", "3": "Seed banks are conservation facilities \u2014 not commercial enterprises, though some seed collections are used to support farmers."}}]}, "summary": "Define biodiversity, explain its importance and describe threats to it and conservation measures.", "theory": [{"content": "BIODIVERSITY is the variety of life on Earth.\n\nIt has two components:\nSPECIES DIVERSITY \u2014 the number of DIFFERENT SPECIES in an area AND the relative abundance of each species.\nGENETIC DIVERSITY \u2014 the variety of ALLELES (different versions of genes) within a species.\n\nHigh species diversity means many different species, each present in reasonable numbers.\nHigh genetic diversity within a species means the population has a wide range of alleles \u2014 making it adaptable.\n\nWhy genetic diversity matters:\nA genetically diverse population can cope with new diseases, climate shifts or environmental changes \u2014 some individuals will have alleles giving resistance or tolerance.\nA genetically uniform population (like a monoculture crop) is vulnerable \u2014 one disease can devastate the whole population.", "heading": "What is Biodiversity?"}, {"content": "High biodiversity provides essential ECOSYSTEM SERVICES that humans depend on:\n\nFood PRODUCTION \u2014 diverse ecosystems provide diverse foods. Wild relatives of crop plants are a genetic reservoir for future crop improvement.\n\nPOLLINATION \u2014 approximately 75% of the world's food crops depend on animal pollinators (bees, butterflies, hoverflies). Loss of pollinator diversity threatens food security.\n\nClean WATER \u2014 wetland plants and soil organisms filter pollutants from water naturally.\n\nClean AIR \u2014 forests and vegetation absorb CO\u2082 and other pollutants.\n\nMEDICINES \u2014 many drugs come from wild species: aspirin from willow, penicillin from a mould, cancer drugs from the Pacific yew tree. Undiscovered species may hold future cures.\n\nECOSYSTEM STABILITY \u2014 more species = more connections = more resilience. If one species declines, others can take over its role.\n\nCLIMATE REGULATION \u2014 forests absorb CO\u2082 and influence rainfall patterns.\n\nETHICAL RESPONSIBILITY \u2014 many argue that all species have a right to exist, regardless of utility to humans.", "heading": "Why Biodiversity Matters"}, {"content": "THREATS:\nHABITAT DESTRUCTION \u2014 deforestation, draining of wetlands, urbanisation, agricultural expansion \u2192 loss of living space for species.\nPOLLUTION \u2014 pesticides, plastic, oil spills, acid rain damage habitats and directly kill organisms.\nINVASIVE SPECIES \u2014 introduced species outcompete or prey on native species (e.g. grey squirrels, American mink, Japanese knotweed).\nOVEREXPLOITATION \u2014 overfishing, overhunting, illegal wildlife trade reducing populations below viable levels.\nCLIMATE CHANGE \u2014 shifting temperature ranges, sea level rise, altered rainfall patterns displace or eliminate species.\n\nCONSERVATION MEASURES:\nPROTECTED AREAS \u2014 national parks, nature reserves, marine protected areas prevent habitat destruction.\nCAPTIVE BREEDING PROGRAMMES \u2014 zoos and wildlife centres breed endangered species to prevent extinction.\nSEED BANKS \u2014 e.g. Svalbard Global Seed Vault stores seeds of thousands of plant varieties as insurance against loss.\nREINTRODUCTION PROGRAMMES \u2014 reintroducing species to habitats where they once lived (e.g. beavers in Scotland, white-tailed eagles in England).\nLEGISLATION \u2014 laws protecting endangered species and their habitats (e.g. CITES, Wildlife and Countryside Act).\nHABITAT RESTORATION \u2014 rewilding projects restore degraded habitats.\nSUSTAINABLE FISHING \u2014 quotas, minimum catch sizes, protected areas to allow fish stocks to recover.", "heading": "Threats to Biodiversity and Conservation"}]};
window.KS4SRC["development-periodic-table"] = {"common_mistake": "Mendeleev arranged elements by RELATIVE ATOMIC MASS \u2014 the MODERN table is arranged by ATOMIC NUMBER. Mendeleev's arrangement had a few inconsistencies because Ar and atomic number don't always match perfectly (e.g. argon and potassium). The modern arrangement by atomic number resolves all these problems.", "key_note": "Newlands: octaves \u2014 every 8th element similar \u2014 rejected (didn't work for all elements, no gaps). Mendeleev: arranged by Ar, left gaps, predicted missing elements \u2014 accepted when predictions proved correct. Modern table: arranged by atomic number (Moseley, 1913).", "matching": {"instruction": "Match each scientist to their contribution to the periodic table.", "pairs": [["Newlands", "Law of Octaves \u2014 every 8th element similar \u2014 not accepted by scientists at the time"], ["Mendeleev", "Left gaps for undiscovered elements, predicted their properties \u2014 table accepted when predictions proved correct"], ["Moseley", "Arranged elements by atomic number (protons) \u2014 resolved inconsistencies in Mendeleev's Ar-based table"]], "title": "Match the Scientist to their Contribution"}, "quiz": {"CF": [{"opts": [["It only worked for the first 16 elements and forced elements into groups regardless of whether properties matched", true], ["Newlands arranged elements by atomic number rather than relative atomic mass", false], ["The law of octaves was never published so other scientists couldn't evaluate it", false], ["Newlands did not leave gaps for undiscovered elements \u2014 but neither did he need to", false]], "q": "Why did the scientific community initially reject Newlands' Law of Octaves?", "wrong_explanations": {"1": "Newlands arranged by RELATIVE ATOMIC MASS \u2014 atomic numbers were not yet known.", "2": "Newlands did publish his work \u2014 it was presented to the Chemical Society in 1866.", "3": "Not leaving gaps was a problem for Mendeleev too initially \u2014 but the bigger issue for Newlands was that his pattern broke down after the first 16 elements."}}, {"opts": [["He predicted properties of undiscovered elements \u2014 and when they were found, the predictions were accurate", true], ["He was the first to arrange elements in order of atomic mass", false], ["He discovered all the noble gases and added them to the table", false], ["His table was the simplest and easiest to remember", false]], "q": "What was the key reason Mendeleev's periodic table was eventually accepted by scientists?", "wrong_explanations": {"1": "Newlands had also arranged by atomic mass \u2014 Mendeleev's key advance was leaving gaps and making testable predictions.", "2": "Noble gases were discovered by other scientists (Ramsay and others) after Mendeleev's original table \u2014 they were later added as Group 0.", "3": "Science accepts models based on EVIDENCE and PREDICTIVE POWER, not simplicity alone."}}], "CH": [{"opts": [["It only worked for the first 16 elements and forced elements into groups regardless of whether properties matched", true], ["Newlands arranged elements by atomic number rather than relative atomic mass", false], ["The law of octaves was never published so other scientists couldn't evaluate it", false], ["Newlands did not leave gaps for undiscovered elements \u2014 but neither did he need to", false]], "q": "Why did the scientific community initially reject Newlands' Law of Octaves?", "wrong_explanations": {"1": "Newlands arranged by RELATIVE ATOMIC MASS \u2014 atomic numbers were not yet known.", "2": "Newlands did publish his work \u2014 it was presented to the Chemical Society in 1866.", "3": "Not leaving gaps was a problem for Mendeleev too initially \u2014 but the bigger issue for Newlands was that his pattern broke down after the first 16 elements."}}, {"opts": [["He predicted properties of undiscovered elements \u2014 and when they were found, the predictions were accurate", true], ["He was the first to arrange elements in order of atomic mass", false], ["He discovered all the noble gases and added them to the table", false], ["His table was the simplest and easiest to remember", false]], "q": "What was the key reason Mendeleev's periodic table was eventually accepted by scientists?", "wrong_explanations": {"1": "Newlands had also arranged by atomic mass \u2014 Mendeleev's key advance was leaving gaps and making testable predictions.", "2": "Noble gases were discovered by other scientists (Ramsay and others) after Mendeleev's original table \u2014 they were later added as Group 0.", "3": "Science accepts models based on EVIDENCE and PREDICTIVE POWER, not simplicity alone."}}], "TF": [{"opts": [["It only worked for the first 16 elements and forced elements into groups regardless of whether properties matched", true], ["Newlands arranged elements by atomic number rather than relative atomic mass", false], ["The law of octaves was never published so other scientists couldn't evaluate it", false], ["Newlands did not leave gaps for undiscovered elements \u2014 but neither did he need to", false]], "q": "Why did the scientific community initially reject Newlands' Law of Octaves?", "wrong_explanations": {"1": "Newlands arranged by RELATIVE ATOMIC MASS \u2014 atomic numbers were not yet known.", "2": "Newlands did publish his work \u2014 it was presented to the Chemical Society in 1866.", "3": "Not leaving gaps was a problem for Mendeleev too initially \u2014 but the bigger issue for Newlands was that his pattern broke down after the first 16 elements."}}, {"opts": [["He predicted properties of undiscovered elements \u2014 and when they were found, the predictions were accurate", true], ["He was the first to arrange elements in order of atomic mass", false], ["He discovered all the noble gases and added them to the table", false], ["His table was the simplest and easiest to remember", false]], "q": "What was the key reason Mendeleev's periodic table was eventually accepted by scientists?", "wrong_explanations": {"1": "Newlands had also arranged by atomic mass \u2014 Mendeleev's key advance was leaving gaps and making testable predictions.", "2": "Noble gases were discovered by other scientists (Ramsay and others) after Mendeleev's original table \u2014 they were later added as Group 0.", "3": "Science accepts models based on EVIDENCE and PREDICTIVE POWER, not simplicity alone."}}], "TH": [{"opts": [["It only worked for the first 16 elements and forced elements into groups regardless of whether properties matched", true], ["Newlands arranged elements by atomic number rather than relative atomic mass", false], ["The law of octaves was never published so other scientists couldn't evaluate it", false], ["Newlands did not leave gaps for undiscovered elements \u2014 but neither did he need to", false]], "q": "Why did the scientific community initially reject Newlands' Law of Octaves?", "wrong_explanations": {"1": "Newlands arranged by RELATIVE ATOMIC MASS \u2014 atomic numbers were not yet known.", "2": "Newlands did publish his work \u2014 it was presented to the Chemical Society in 1866.", "3": "Not leaving gaps was a problem for Mendeleev too initially \u2014 but the bigger issue for Newlands was that his pattern broke down after the first 16 elements."}}, {"opts": [["He predicted properties of undiscovered elements \u2014 and when they were found, the predictions were accurate", true], ["He was the first to arrange elements in order of atomic mass", false], ["He discovered all the noble gases and added them to the table", false], ["His table was the simplest and easiest to remember", false]], "q": "What was the key reason Mendeleev's periodic table was eventually accepted by scientists?", "wrong_explanations": {"1": "Newlands had also arranged by atomic mass \u2014 Mendeleev's key advance was leaving gaps and making testable predictions.", "2": "Noble gases were discovered by other scientists (Ramsay and others) after Mendeleev's original table \u2014 they were later added as Group 0.", "3": "Science accepts models based on EVIDENCE and PREDICTIVE POWER, not simplicity alone."}}]}, "summary": "Describe how the periodic table developed, including Newlands and Mendeleev's contributions.", "theory": [{"content": "Before atomic numbers were understood, scientists tried to classify elements based on RELATIVE ATOMIC MASS.\n\nJOHN NEWLANDS \u2014 Law of Octaves (1864):\nArranged elements by increasing Ar.\nNoticed that every 8th element had similar properties \u2014 called it the 'Law of Octaves' (like musical notes).\nLimitations:\nOnly worked for the first 16 elements.\nForced elements into groups even when properties didn't match.\nLeft no gaps for undiscovered elements.\nThe scientific community did not accept his work.\n\nDMITRI MENDELEEV \u2014 first successful periodic table (1869):\nAlso arranged elements by increasing Ar.\nKey improvements over Newlands:\nLeft GAPS for undiscovered elements \u2014 predicted their properties.\nRearranged some elements to make groups match better (putting chemical properties above strict Ar order).\nPredicted EKA-SILICON (now known as germanium) \u2014 when it was discovered in 1886, its properties closely matched Mendeleev's prediction.\nThis predictive power convinced the scientific community to accept the table.", "heading": "Early Attempts at Classification"}, {"content": "The modern periodic table was only possible after the discovery of subatomic particles.\n\nHENRY MOSELEY (1913):\nUsed X-ray experiments to determine ATOMIC NUMBERS of elements.\nRealised elements should be arranged by ATOMIC NUMBER (protons), not atomic mass.\nThis resolved several inconsistencies in Mendeleev's table where some elements seemed in the wrong order when arranged by Ar.\n\nKey improvement: arranging by atomic number places elements in the correct groups without exception \u2014 it is the atomic number (protons = electrons) that determines chemical properties, not mass.\n\nDISCOVERY OF NOBLE GASES:\nArgon (1894) and other noble gases were discovered AFTER Mendeleev's table \u2014 but they fit perfectly as a new Group 0.\nThis was further evidence for the validity of the periodic table structure.", "heading": "The Modern Periodic Table"}, {"content": "Mendeleev's table was eventually accepted by the scientific community for three main reasons:\n\n1. PREDICTIVE POWER: He predicted properties of undiscovered elements (eka-aluminium = gallium, eka-silicon = germanium, eka-boron = scandium). When discovered, they matched his predictions closely.\n\n2. GAPS: Leaving gaps was a bold scientific decision \u2014 it showed the table was a genuine model of underlying patterns, not just a classification of known elements.\n\n3. EXPLAINING PATTERNS: The table explained why elements in the same group reacted similarly \u2014 it made chemistry more systematic and predictable.\n\nScience accepts models when they successfully PREDICT new observations \u2014 Mendeleev's table did exactly this.", "heading": "Why Mendeleev's Table was Accepted"}]};
window.KS4SRC["uses-em-waves"] = {"common_mistake": "MRI scanners use RADIO WAVES (not X-rays) \u2014 they are safe for soft tissue imaging with no ionising radiation. X-rays are used for imaging BONE and dense structures. Also: microwaves for SATELLITE communication (pass through ionosphere); radio waves for BROADCAST (reflect off ionosphere).", "higher": "Explain why different wavelengths of EM radiation are used for different applications in terms of their properties \u2014 penetration, absorption, reflection and refraction behaviour. Evaluate the hazards and benefits of each type in context (e.g. X-rays vs MRI vs ultrasound for medical imaging). Explain how optical fibres work using total internal reflection.", "key_note": "Radio: broadcast, MRI. Microwave: satellites, phones, radar, cooking. IR: heating, remote controls, night vision, fibre optics. Visible: photography, fibre optics, photosynthesis. UV: sterilisation, fluorescence, vitamin D. X-ray: medical imaging, airport security, CT. Gamma: radiotherapy, sterilisation, tracers.", "matching": {"instruction": "Match each application to the EM wave type used.", "pairs": [["Radio waves", "MRI scanner \u2014 safe for soft tissue, no ionising radiation"], ["Microwaves", "Satellite communication \u2014 passes through ionosphere to reach satellites"], ["Infrared", "TV remote control \u2014 pulses of IR carry the signal to the TV"], ["X-rays", "Medical imaging of bones \u2014 absorbed by dense bone, transmitted by soft tissue"], ["Gamma rays", "Radiotherapy \u2014 focused beams kill cancer cells"]], "title": "EM Wave Applications"}, "quiz": {"CF": [{"opts": [["Microwaves pass through the ionosphere \u2014 radio waves reflect off it, preventing them from reaching satellites in orbit", true], ["Microwaves are more powerful \u2014 they reach greater distances than radio waves", false], ["Radio waves are dangerous at high altitude \u2014 microwaves are safer for satellite use", false], ["Satellites can only detect microwaves \u2014 their receivers are not compatible with radio waves", false]], "q": "Why are microwaves used for satellite communications rather than radio waves?", "wrong_explanations": {"1": "Power determines signal strength at a given distance \u2014 but all EM waves travel at the same speed. The key distinction is IONOSPHERE INTERACTION.", "2": "Safety is not the relevant factor \u2014 the ionosphere physically reflects (most) radio waves back to Earth.", "3": "This is backwards \u2014 it's the PHYSICS of ionosphere reflection, not receiver incompatibility, that determines which EM type is used."}}, {"opts": [["UV has enough energy to damage DNA in microorganisms \u2014 killing or inactivating bacteria and viruses", true], ["UV heats the equipment to high temperatures, killing microorganisms by heat", false], ["UV is absorbed by metal \u2014 heating the equipment surface to kill bacteria", false], ["UV converts oxygen to ozone, which then kills bacteria chemically", false]], "q": "UV light is used to sterilise medical equipment. Why is UV effective for this?", "wrong_explanations": {"1": "UV can cause some warming but it's not the primary mechanism \u2014 UV sterilisation works through DNA damage (photochemical action), not significant heating.", "2": "UV sterilisation is used for transparent surfaces, water, and air \u2014 metal surfaces are typically sterilised by heat or chemicals.", "3": "UV can produce some ozone, but the primary sterilisation mechanism is direct DNA damage from UV photons \u2014 not ozone."}}], "CH": [{"opts": [["Microwaves pass through the ionosphere \u2014 radio waves reflect off it, preventing them from reaching satellites in orbit", true], ["Microwaves are more powerful \u2014 they reach greater distances than radio waves", false], ["Radio waves are dangerous at high altitude \u2014 microwaves are safer for satellite use", false], ["Satellites can only detect microwaves \u2014 their receivers are not compatible with radio waves", false]], "q": "Why are microwaves used for satellite communications rather than radio waves?", "wrong_explanations": {"1": "Power determines signal strength at a given distance \u2014 but all EM waves travel at the same speed. The key distinction is IONOSPHERE INTERACTION.", "2": "Safety is not the relevant factor \u2014 the ionosphere physically reflects (most) radio waves back to Earth.", "3": "This is backwards \u2014 it's the PHYSICS of ionosphere reflection, not receiver incompatibility, that determines which EM type is used."}}, {"opts": [["UV has enough energy to damage DNA in microorganisms \u2014 killing or inactivating bacteria and viruses", true], ["UV heats the equipment to high temperatures, killing microorganisms by heat", false], ["UV is absorbed by metal \u2014 heating the equipment surface to kill bacteria", false], ["UV converts oxygen to ozone, which then kills bacteria chemically", false]], "q": "UV light is used to sterilise medical equipment. Why is UV effective for this?", "wrong_explanations": {"1": "UV can cause some warming but it's not the primary mechanism \u2014 UV sterilisation works through DNA damage (photochemical action), not significant heating.", "2": "UV sterilisation is used for transparent surfaces, water, and air \u2014 metal surfaces are typically sterilised by heat or chemicals.", "3": "UV can produce some ozone, but the primary sterilisation mechanism is direct DNA damage from UV photons \u2014 not ozone."}}], "TF": [{"opts": [["Microwaves pass through the ionosphere \u2014 radio waves reflect off it, preventing them from reaching satellites in orbit", true], ["Microwaves are more powerful \u2014 they reach greater distances than radio waves", false], ["Radio waves are dangerous at high altitude \u2014 microwaves are safer for satellite use", false], ["Satellites can only detect microwaves \u2014 their receivers are not compatible with radio waves", false]], "q": "Why are microwaves used for satellite communications rather than radio waves?", "wrong_explanations": {"1": "Power determines signal strength at a given distance \u2014 but all EM waves travel at the same speed. The key distinction is IONOSPHERE INTERACTION.", "2": "Safety is not the relevant factor \u2014 the ionosphere physically reflects (most) radio waves back to Earth.", "3": "This is backwards \u2014 it's the PHYSICS of ionosphere reflection, not receiver incompatibility, that determines which EM type is used."}}, {"opts": [["UV has enough energy to damage DNA in microorganisms \u2014 killing or inactivating bacteria and viruses", true], ["UV heats the equipment to high temperatures, killing microorganisms by heat", false], ["UV is absorbed by metal \u2014 heating the equipment surface to kill bacteria", false], ["UV converts oxygen to ozone, which then kills bacteria chemically", false]], "q": "UV light is used to sterilise medical equipment. Why is UV effective for this?", "wrong_explanations": {"1": "UV can cause some warming but it's not the primary mechanism \u2014 UV sterilisation works through DNA damage (photochemical action), not significant heating.", "2": "UV sterilisation is used for transparent surfaces, water, and air \u2014 metal surfaces are typically sterilised by heat or chemicals.", "3": "UV can produce some ozone, but the primary sterilisation mechanism is direct DNA damage from UV photons \u2014 not ozone."}}], "TH": [{"opts": [["Microwaves pass through the ionosphere \u2014 radio waves reflect off it, preventing them from reaching satellites in orbit", true], ["Microwaves are more powerful \u2014 they reach greater distances than radio waves", false], ["Radio waves are dangerous at high altitude \u2014 microwaves are safer for satellite use", false], ["Satellites can only detect microwaves \u2014 their receivers are not compatible with radio waves", false]], "q": "Why are microwaves used for satellite communications rather than radio waves?", "wrong_explanations": {"1": "Power determines signal strength at a given distance \u2014 but all EM waves travel at the same speed. The key distinction is IONOSPHERE INTERACTION.", "2": "Safety is not the relevant factor \u2014 the ionosphere physically reflects (most) radio waves back to Earth.", "3": "This is backwards \u2014 it's the PHYSICS of ionosphere reflection, not receiver incompatibility, that determines which EM type is used."}}, {"opts": [["UV has enough energy to damage DNA in microorganisms \u2014 killing or inactivating bacteria and viruses", true], ["UV heats the equipment to high temperatures, killing microorganisms by heat", false], ["UV is absorbed by metal \u2014 heating the equipment surface to kill bacteria", false], ["UV converts oxygen to ozone, which then kills bacteria chemically", false]], "q": "UV light is used to sterilise medical equipment. Why is UV effective for this?", "wrong_explanations": {"1": "UV can cause some warming but it's not the primary mechanism \u2014 UV sterilisation works through DNA damage (photochemical action), not significant heating.", "2": "UV sterilisation is used for transparent surfaces, water, and air \u2014 metal surfaces are typically sterilised by heat or chemicals.", "3": "UV can produce some ozone, but the primary sterilisation mechanism is direct DNA damage from UV photons \u2014 not ozone."}}]}, "summary": "Describe the uses of each type of electromagnetic wave and explain why each type is suitable.", "theory": [{"content": "RADIO WAVES:\nBROADCASTING: AM and FM radio, TV broadcasts \u2014 travel long distances, reflect off ionosphere.\nCOMMUNICATION: aircraft, ships, emergency services.\nASTRONOMY: radio telescopes detect radio waves from distant stars and galaxies.\nMRI SCANNERS: radio waves + magnetic field \u2192 detailed images of soft tissue (no ionising radiation).\n\nMICROWAVES:\nMOBILE PHONES AND WIFI: short-range communication.\nSATELLITE COMMUNICATION: microwaves pass through the atmosphere and ionosphere (radio waves reflect off ionosphere \u2014 limited for satellite use).\nMICROWAVE OVENS: microwave frequency matches water molecules' resonance \u2192 absorbed \u2192 food heats from inside.\nRADAR: detect aircraft, ships, weather systems \u2014 measure distance by timing reflection.", "heading": "Uses of Radio Waves and Microwaves"}, {"content": "INFRARED (IR):\nHEATING: electric heaters, grills \u2014 absorbed by surfaces, converted to heat.\nREMOTE CONTROLS: TV, DVD players \u2014 IR pulses carry coded signals.\nFIBRE OPTICS: IR carried along optical fibres for high-speed internet.\nNIGHT VISION CAMERAS: detect IR emitted by warm bodies \u2014 useful in darkness.\nTHERMAL IMAGING: medical, security, wildlife observation.\n\nVISIBLE LIGHT:\nPHOTOGRAPHY: cameras capture visible light.\nFIBRE OPTICS: carries data as light pulses \u2014 basis of broadband internet.\nPHOTOSYNTHESIS: plants absorb red and blue light.\nLASERS: surgery, barcode scanners, DVD reading.\n\nULTRAVIOLET (UV):\nSTERILISATION: UV kills bacteria and viruses \u2014 used in hospitals and water treatment.\nFLUORESCENCE: some materials emit visible light when absorbing UV \u2014 security markings, fluorescent lamps.\nBLACK LIGHTS: detect forged bank notes (UV-reactive ink).\nVITAMIN D PRODUCTION: skin produces vitamin D when exposed to UV.", "heading": "Uses of Infrared, Visible and Ultraviolet"}, {"content": "X-RAYS:\nMEDICAL IMAGING: pass through soft tissue, absorbed by bone \u2192 shadow on film/detector.\nCT SCANS: multiple X-ray beams \u2192 3D image of internal structures.\nAIRPORT SECURITY: luggage scanning \u2014 detect metal, explosives.\nMATERIAL TESTING: checking for cracks in metal castings and welds.\n\nGAMMA RAYS:\nCANCER TREATMENT (radiotherapy): focused beams kill tumour cells.\nST ERILISATION of medical equipment: kills all microorganisms without heat.\nFOOD IRRADIATION: kills bacteria in food \u2192 longer shelf life.\nMEDICAL TRACERS: gamma-emitting radioisotopes injected \u2192 gamma camera detects distribution in body \u2192 reveals organ function.\nTHICKNESS MONITORING: detect gamma penetration through materials in manufacturing.\n\nMATCHING APPLICATION TO WAVE TYPE:\nThe wave chosen matches its properties to the application:\nMust penetrate enough \u2192 not be absorbed too quickly.\nMust interact appropriately with the target material.\nHazard must be managed \u2014 ionising types minimised.", "heading": "Uses of X-rays and Gamma Rays"}]};
